export const MINIMUM_SOURCE_DATA_ITEMS_TRIVIA = 4;
export const MINIMUM_PAIRS_MEMORY = 2; 
export const MINIMUM_VERSES_ORDER_VERSE = 1; 
export const MINIMUM_VERSES_RECITE_VERSE = 1; // Mínimo de versos para el juego de recitar.

import React, { useState, useCallback, useEffect } from 'react';
import { 
  GameScreenState, GameMode, TriviaCategory, TriviaQuestion, DifficultySetting, 
  MemoryDifficultySetting, SourceDataItem, TriviaOption, GameEndPayload, MemoryCardData,
  OrderVerseItem, OrderVerseDifficultySetting, ReciteVerseItem, ReciteVerseDifficultySetting, Difficulty 
} from './types';
import { 
  TRIVIA_SOURCE_DATA, CATEGORIES, DIFFICULTY_LEVELS, MEMORY_DIFFICULTY_SETTINGS, 
  ORDER_VERSE_DIFFICULTY_SETTINGS, RECITE_VERSE_DIFFICULTY_SETTINGS,
  MINIMUM_SOURCE_DATA_ITEMS_TRIVIA, MINIMUM_PAIRS_MEMORY, MINIMUM_VERSES_ORDER_VERSE, MINIMUM_VERSES_RECITE_VERSE
} from './constants';
import HomeScreen from './components/HomeScreen';
import GameScreen from './components/GameScreen'; 
import MemoryGameScreen from './components/MemoryGameScreen';
import OrderVerseScreen from './components/OrderVerseScreen'; 
import ReciteVerseScreen from './components/ReciteVerseScreen';
import FinalScreen from './components/FinalScreen';

const shuffleArray = <T,>(array: T[]): T[] => {
  const newArray = [...array];
  for (let i = newArray.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [newArray[i], newArray[j]] = [newArray[j], newArray[i]];
  }
  return newArray;
};

const tokenizeVerse = (text: string): string[] => {
  return text.split(/\s+/).filter(word => word.length > 0).map(word => word.trim());
};

const LOGO_URL = "https://i.postimg.cc/9MZ6CRqt/Logo.png";

const IntroAnimationScreen: React.FC<{ logoSrc: string }> = ({ logoSrc }) => {
  return (
    <div className="fixed top-0 left-0 w-full h-full flex flex-col items-center justify-center bg-gradient-celestial z-50 anim-fade-in">
      <img src={logoSrc} alt="Logo Defensores de la Fe" className="w-48 h-auto md:w-64 intro-logo-animate" />
      <p className="text-xl font-serif text-gray-700 mt-6 animate-pulse">Cargando Desafío Bíblico...</p>
    </div>
  );
};

const App: React.FC = () => {
  const [currentScreen, setCurrentScreen] = useState<GameScreenState>(GameScreenState.Home);
  const [selectedGameMode, setSelectedGameMode] = useState<GameMode>(GameMode.TRIVIA);
  const [activeGameSettings, setActiveGameSettings] = useState<DifficultySetting | MemoryDifficultySetting | OrderVerseDifficultySetting | ReciteVerseDifficultySetting | null>(null);
  const [activeCategory, setActiveCategory] = useState<TriviaCategory | undefined>(CATEGORIES[0]);

  const [gameResults, setGameResults] = useState<GameEndPayload | null>(null);

  const [triviaQuestions, setTriviaQuestions] = useState<TriviaQuestion[]>([]);
  const [memoryCards, setMemoryCards] = useState<MemoryCardData[]>([]);
  const [orderVerseItems, setOrderVerseItems] = useState<OrderVerseItem[]>([]);
  const [reciteVerseItems, setReciteVerseItems] = useState<ReciteVerseItem[]>([]);

  const [viewAnimation, setViewAnimation] = useState('anim-fade-in');
  const [isLoading, setIsLoading] = useState(false);
  const [appReady, setAppReady] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      setAppReady(true);
    }, 2800); // Duración de la pantalla de introducción (ajustar según la animación)
    return () => clearTimeout(timer);
  }, []);

  const navigateTo = useCallback((newScreen: GameScreenState) => {
    setViewAnimation('anim-fade-out');
    setTimeout(() => {
      setCurrentScreen(newScreen);
      setViewAnimation('anim-fade-in');
      setIsLoading(false); 
    }, 300); 
  }, []);

  const prepareTriviaQuestions = useCallback((category: TriviaCategory, difficulty: DifficultySetting): boolean => {
    if (TRIVIA_SOURCE_DATA.length < MINIMUM_SOURCE_DATA_ITEMS_TRIVIA) {
        alert(`No hay suficientes datos base (${TRIVIA_SOURCE_DATA.length}) para Trivia. Se requieren al menos ${MINIMUM_SOURCE_DATA_ITEMS_TRIVIA}.`);
        return false;
    }
    let candidateBaseItems: SourceDataItem[] = category === TriviaCategory.ALL ? 
        [...TRIVIA_SOURCE_DATA] : 
        TRIVIA_SOURCE_DATA.filter(item => item.category === category);

    // If -1 (Unlimited/Training), use all available items
    const numQuestionsToSelect = difficulty.questions === -1 ? candidateBaseItems.length : difficulty.questions;

    if (candidateBaseItems.length === 0) {
      alert(`No hay preguntas de trivia disponibles para la categoría "${category}".`);
      return false;
    }
    if (candidateBaseItems.length < numQuestionsToSelect && difficulty.questions !== -1) {
      alert(`No hay suficientes preguntas base (${candidateBaseItems.length}) en la categoría "${category}" para la dificultad "${difficulty.level}" (${numQuestionsToSelect} requeridas). Se usarán ${candidateBaseItems.length} preguntas.`);
    }

    const actualNumQuestions = Math.min(candidateBaseItems.length, numQuestionsToSelect);
    const selectedBaseItems = shuffleArray(candidateBaseItems).slice(0, actualNumQuestions);

    if (selectedBaseItems.length === 0) {
        alert(`No se pudieron seleccionar preguntas de trivia para la categoría "${category}".`);
        return false;
    }

    const newGameQuestions: TriviaQuestion[] = selectedBaseItems.map((baseItem) => {
      const correctOption: TriviaOption = { text: baseItem.correctAnswer, isCorrect: true };
      let incorrectAnswersPool = TRIVIA_SOURCE_DATA
        .filter(item => item.id !== baseItem.id) 
        .map(item => item.correctAnswer);

      incorrectAnswersPool = Array.from(new Set(incorrectAnswersPool.filter(ans => ans !== baseItem.correctAnswer)));
      const numberOfIncorrectOptionsToPick = Math.min(3, incorrectAnswersPool.length); 
      const incorrectOptionsTexts = shuffleArray(incorrectAnswersPool).slice(0, numberOfIncorrectOptionsToPick);
      const incorrectOptions: TriviaOption[] = incorrectOptionsTexts.map(text => ({ text, isCorrect: false }));
      const allOptions = shuffleArray([correctOption, ...incorrectOptions]);

      return {
        id: baseItem.id,
        verse: baseItem.text,
        options: allOptions,
        category: baseItem.category,
      };
    });

    const validGameQuestions = newGameQuestions.filter(q => q.options.length >= 2);
    if (validGameQuestions.length === 0 && actualNumQuestions > 0) {
        alert("Error: No se pudieron generar preguntas de trivia con suficientes opciones.");
        return false;
    }
    if (validGameQuestions.length < actualNumQuestions) {
        alert(`Advertencia: Algunas preguntas de trivia (${actualNumQuestions - validGameQuestions.length}) fueron omitidas por falta de opciones.`);
    }
    setTriviaQuestions(validGameQuestions);
    return validGameQuestions.length > 0;
  }, []);

  const prepareMemoryCards = useCallback((difficulty: MemoryDifficultySetting, category?: TriviaCategory): boolean => {
    const numPairs = difficulty.pairs;
    let sourceForMemory = TRIVIA_SOURCE_DATA;

    if (category && category !== TriviaCategory.ALL) {
      sourceForMemory = TRIVIA_SOURCE_DATA.filter(item => item.category === category);
    }

    if (sourceForMemory.length < numPairs) {
      const categoryMessage = category && category !== TriviaCategory.ALL ? ` en la categoría "${category}"` : "";
      alert(`No hay suficientes datos base (${sourceForMemory.length})${categoryMessage} para el juego de memoria de ${numPairs} pares. Se requieren al menos ${numPairs} versos únicos.`);
      return false;
    }
    if (numPairs < MINIMUM_PAIRS_MEMORY) {
       alert(`El número de pares (${numPairs}) es muy bajo. Se requieren al menos ${MINIMUM_PAIRS_MEMORY} pares.`);
       return false;
    }

    const shuffledSource = shuffleArray([...sourceForMemory]);
    const selectedItems = shuffledSource.slice(0, numPairs);

    if (selectedItems.length < numPairs) {
        const categoryMessage = category && category !== TriviaCategory.ALL ? ` de la categoría "${category}"` : "";
        alert(`No se pudieron seleccionar suficientes versos únicos (${selectedItems.length}/${numPairs})${categoryMessage} para el juego de memoria.`);
        return false;
    }

    let newMemoryCards: MemoryCardData[] = [];
    selectedItems.forEach((item) => {
      const pairId = item.id;
      newMemoryCards.push({ id: `${pairId}_text`, pairId: pairId, content: item.text, isFlipped: false, isMatched: false });
      newMemoryCards.push({ id: `${pairId}_ref`, pairId: pairId, content: item.correctAnswer, isFlipped: false, isMatched: false });
    });

    setMemoryCards(shuffleArray(newMemoryCards));
    return true;
  }, []);

  const prepareOrderVerseItems = useCallback((difficulty: OrderVerseDifficultySetting, category?: TriviaCategory): boolean => {
    // If -1 (Unlimited/Training), use all available items
    let sourceForOrderVerse = TRIVIA_SOURCE_DATA;

    if (category && category !== TriviaCategory.ALL) {
        sourceForOrderVerse = TRIVIA_SOURCE_DATA.filter(item => item.category === category);
    }

    const numVerses = difficulty.versesToOrder === -1 ? sourceForOrderVerse.length : difficulty.versesToOrder;

    if (sourceForOrderVerse.length < numVerses && difficulty.versesToOrder !== -1) {
        const categoryMessage = category && category !== TriviaCategory.ALL ? ` en la categoría "${category}"` : "";
        alert(`No hay suficientes versículos (${sourceForOrderVerse.length})${categoryMessage} para el juego de "Ordenar Versículo" de ${numVerses} ítems. Se requieren al menos ${numVerses}.`);
        return false;
    }
    if (sourceForOrderVerse.length === 0) {
        alert("No hay versículos disponibles para ordenar en esta categoría.");
        return false;
    }

    const shuffledSource = shuffleArray([...sourceForOrderVerse]);
    const selectedItems = shuffledSource.slice(0, numVerses);

    const newOrderVerseItems: OrderVerseItem[] = selectedItems.map(item => {
        const correctWords = tokenizeVerse(item.text);
        return {
            id: item.id,
            reference: item.correctAnswer,
            category: item.category,
            correctOrderText: item.text,
            words: shuffleArray([...correctWords]), 
            correctWordOrder: correctWords, 
        };
    });
    setOrderVerseItems(newOrderVerseItems);
    return true;
  }, []);

  const prepareReciteVerseItems = useCallback((difficulty: ReciteVerseDifficultySetting, category?: TriviaCategory): boolean => {
    let sourceData = TRIVIA_SOURCE_DATA;

    if (category && category !== TriviaCategory.ALL) {
        sourceData = TRIVIA_SOURCE_DATA.filter(item => item.category === category);
    }

    // If -1 (Unlimited/Training), use all available items
    const numVerses = difficulty.versesToRecite === -1 ? sourceData.length : difficulty.versesToRecite;

    if (sourceData.length < numVerses && difficulty.versesToRecite !== -1) {
        const categoryMsg = category && category !== TriviaCategory.ALL ? ` en la categoría "${category}"` : "";
        alert(`No hay suficientes versículos (${sourceData.length})${categoryMsg} para "Recitar Versículo" (${numVerses} requeridos).`);
        return false;
    }
    if (sourceData.length === 0) {
        alert("No hay versículos disponibles para recitar en esta categoría.");
        return false;
    }

    const selectedItems = shuffleArray([...sourceData]).slice(0, numVerses);

    const newReciteItems: ReciteVerseItem[] = selectedItems.map(item => ({
        id: item.id,
        reference: item.correctAnswer,
        category: item.category,
        fullText: item.text,
        words: tokenizeVerse(item.text),
    }));
    setReciteVerseItems(newReciteItems);
    return true;
  }, []);

  const handleStartGame = useCallback((
    gameMode: GameMode,
    settings: DifficultySetting | MemoryDifficultySetting | OrderVerseDifficultySetting | ReciteVerseDifficultySetting,
    category?: TriviaCategory
  ) => {
    setIsLoading(true);
    setSelectedGameMode(gameMode);
    setActiveGameSettings(settings);
    setActiveCategory(category); 
    setGameResults(null); 
    setTriviaQuestions([]);
    setMemoryCards([]);
    setOrderVerseItems([]);
    setReciteVerseItems([]);

    let ready = false;
    if (gameMode === GameMode.TRIVIA) {
      ready = prepareTriviaQuestions(category!, settings as DifficultySetting);
    } else if (gameMode === GameMode.MEMORY) {
      ready = prepareMemoryCards(settings as MemoryDifficultySetting, category);
    } else if (gameMode === GameMode.ORDER_VERSE) {
      ready = prepareOrderVerseItems(settings as OrderVerseDifficultySetting, category);
    } else if (gameMode === GameMode.RECITE_VERSE) {
      ready = prepareReciteVerseItems(settings as ReciteVerseDifficultySetting, category);
    }

    if (ready) {
      navigateTo(GameScreenState.Playing);
    } else {
      setIsLoading(false);
    }
  }, [prepareTriviaQuestions, prepareMemoryCards, prepareOrderVerseItems, prepareReciteVerseItems, navigateTo]);

  const handleGameEnd = useCallback((results: GameEndPayload) => {
    setGameResults(results);
    navigateTo(GameScreenState.Results);
  }, [navigateTo]);

  const handlePlayAgain = useCallback(() => {
    if (!activeGameSettings || !selectedGameMode) {
        navigateTo(GameScreenState.Home); 
        return;
    }
    setIsLoading(true);

    let ready = false;
    if (selectedGameMode === GameMode.TRIVIA && activeGameSettings) {
      ready = prepareTriviaQuestions(activeCategory!, activeGameSettings as DifficultySetting);
    } else if (selectedGameMode === GameMode.MEMORY && activeGameSettings) {
      ready = prepareMemoryCards(activeGameSettings as MemoryDifficultySetting, activeCategory);
    } else if (selectedGameMode === GameMode.ORDER_VERSE && activeGameSettings) {
      ready = prepareOrderVerseItems(activeGameSettings as OrderVerseDifficultySetting, activeCategory);
    } else if (selectedGameMode === GameMode.RECITE_VERSE && activeGameSettings) {
      ready = prepareReciteVerseItems(activeGameSettings as ReciteVerseDifficultySetting, activeCategory);
    }

    if (ready) {
        navigateTo(GameScreenState.Playing);
    } else {
        setIsLoading(false);
        navigateTo(GameScreenState.Home);
    }
  }, [selectedGameMode, activeGameSettings, activeCategory, prepareTriviaQuestions, prepareMemoryCards, prepareOrderVerseItems, prepareReciteVerseItems, navigateTo]);

  const handleChangeSettings = useCallback(() => {
    navigateTo(GameScreenState.Home);
  }, [navigateTo]);

  const renderScreen = () => {
    if (isLoading && (currentScreen === GameScreenState.Home || currentScreen === GameScreenState.Playing)) { 
        return <div className="text-center p-8 text-xl font-semibold text-gray-700">Preparando juego...</div>;
    }

    // Helper to determine if we are in training mode
    const isTrainingMode = activeGameSettings?.level === Difficulty.EASY;

    switch (currentScreen) {
      case GameScreenState.Home:
        return (
          <HomeScreen
            onStartGame={handleStartGame}
            disabled={isLoading}
          />
        );
      case GameScreenState.Playing:
        if (selectedGameMode === GameMode.TRIVIA) {
          if (triviaQuestions.length === 0 || !activeGameSettings) {
              navigateTo(GameScreenState.Home); 
              return <div className="text-center p-8 text-gray-700">Error: No hay preguntas de trivia. Volviendo...</div>; 
          }
          return <GameScreen 
                    questions={triviaQuestions} 
                    onGameEnd={handleGameEnd} 
                    timerDuration={(activeGameSettings as DifficultySetting).timerDuration}
                    isTraining={isTrainingMode}
                  />;
        } else if (selectedGameMode === GameMode.MEMORY) {
            if (memoryCards.length === 0 || !activeGameSettings) {
              navigateTo(GameScreenState.Home); 
              return <div className="text-center p-8 text-gray-700">Error: No hay cartas de memoria. Volviendo...</div>;
            }
            return <MemoryGameScreen
                      cards={memoryCards}
                      difficulty={activeGameSettings as MemoryDifficultySetting}
                      onGameEnd={handleGameEnd}
                      isTraining={isTrainingMode}
                    />;
        } else if (selectedGameMode === GameMode.ORDER_VERSE) {
            if (orderVerseItems.length === 0 || !activeGameSettings) {
                navigateTo(GameScreenState.Home);
                return <div className="text-center p-8 text-gray-700">Error: No hay versículos para ordenar. Volviendo...</div>;
            }
            return <OrderVerseScreen
                      items={orderVerseItems}
                      difficulty={activeGameSettings as OrderVerseDifficultySetting}
                      onGameEnd={handleGameEnd}
                      isTraining={isTrainingMode}
                    />;
        } else if (selectedGameMode === GameMode.RECITE_VERSE) {
            if (reciteVerseItems.length === 0 || !activeGameSettings) {
                navigateTo(GameScreenState.Home);
                return <div className="text-center p-8 text-gray-700">Error: No hay versículos para recitar. Volviendo...</div>;
            }
            return <ReciteVerseScreen
                      items={reciteVerseItems}
                      difficultySettings={activeGameSettings as ReciteVerseDifficultySetting}
                      onGameEnd={handleGameEnd}
                      isTraining={isTrainingMode}
                    />;
        }
        navigateTo(GameScreenState.Home);
        return null;

      case GameScreenState.Results:
        if (!gameResults || !activeGameSettings) {
            navigateTo(GameScreenState.Home); 
            return <div className="text-center p-8 text-gray-700">Error: No hay resultados. Volviendo...</div>;
        }
        return (
          <FinalScreen
            results={gameResults}
            onPlayAgain={handlePlayAgain} 
            onChangeSettings={handleChangeSettings}
          />
        );
      default: 
        navigateTo(GameScreenState.Home);
        return null;
    }
  };

  if (!appReady) {
    return <IntroAnimationScreen logoSrc={LOGO_URL} />;
  }

  return (
    <div className={`min-h-screen bg-gradient-celestial text-gray-800 flex flex-col font-sans ${appReady ? 'anim-fade-in' : 'opacity-0'}`}>
      <header className="w-full bg-white/80 backdrop-blur-md shadow-md py-2 px-4 sticky top-0 z-30">
        <div className="max-w-6xl mx-auto flex items-center">
          <button 
            onClick={() => navigateTo(GameScreenState.Home)}
            aria-label="Volver a la pantalla de inicio"
            className="p-0 bg-transparent border-none cursor-pointer focus:outline-none focus:ring-2 focus:ring-amber-500 rounded-md"
          >
            <img src={LOGO_URL} alt="Logo Defensores de la Fe" className="h-10 w-auto" /> 
          </button>
        </div>
      </header>

      <main className="flex-grow flex flex-col items-center justify-center p-2 sm:p-4">
        <div className={`w-full max-w-2xl ${viewAnimation}`}>
          {renderScreen()}
        </div>
      </main>

      <footer className="w-full bg-gray-100/60 backdrop-blur-sm text-gray-600 text-xs text-center p-3 mt-auto">
        <div className="max-w-6xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-2">
          <div className="flex items-center gap-2">
            <img src={LOGO_URL} alt="Logo Defensores de la Fe" className="h-6 w-auto opacity-75" />
            <span>© {new Date().getFullYear()} Iglesia Defensores de la Fe Cristiana. Todos los derechos reservados.</span>
          </div>
          <div className="flex space-x-4 text-lg">
            <a href="#" aria-label="Facebook" className="hover:text-amber-600"><i className="fab fa-facebook-f"></i></a>
            <a href="#" aria-label="Instagram" className="hover:text-amber-600"><i className="fab fa-instagram"></i></a>
            <a href="#" aria-label="YouTube" className="hover:text-amber-600"><i className="fab fa-youtube"></i></a>
          </div>
