import React, { useState, useEffect, useCallback } from 'react';
import { TriviaQuestion, SelectedAnswerInfo, GameEndPayload, TriviaGameEndPayload } from '../types';
import Button from './Button';
import ProgressBar from './ProgressBar';

const FEEDBACK_DISPLAY_TIME_MS = 1800;
const TIMEOUT_SELECTED_INDEX = -1; // Special index to denote a timeout

interface GameScreenProps {
  questions: TriviaQuestion[];
  onGameEnd: (results: GameEndPayload) => void; 
  timerDuration: number; 
  isTraining?: boolean;
}

const GameScreen: React.FC<GameScreenProps> = ({ questions, onGameEnd, timerDuration, isTraining = false }) => {
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [netScore, setNetScore] = useState(0);
  const [correctAnswersCount, setCorrectAnswersCount] = useState(0);
  const [selectedAnswerInfo, setSelectedAnswerInfo] = useState<SelectedAnswerInfo | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [questionContainerClass, setQuestionContainerClass] = useState('anim-fade-in');
  const [timeLeft, setTimeLeft] = useState(timerDuration);
  const [timerId, setTimerId] = useState<number | null>(null);

  const currentQuestion = questions[currentQuestionIndex];
  const totalQuestions = questions.length;

  const handleFinishTraining = useCallback(() => {
    // Finish immediately with current stats
    // We treat 'totalQuestions' as 'questions answered so far' for the report
    const results: TriviaGameEndPayload = {
        type: 'trivia',
        netScore,
        correctAnswersCount,
        totalQuestions: currentQuestionIndex + (isAnswered ? 1 : 0), // Count current if answered
      };
      onGameEnd(results);
  }, [netScore, correctAnswersCount, currentQuestionIndex, isAnswered, onGameEnd]);

  const proceedToNextPhase = useCallback(() => {
    setTimeout(() => {
      if (currentQuestionIndex < questions.length - 1) {
        setCurrentQuestionIndex(prevIndex => prevIndex + 1);
      } else {
        const results: TriviaGameEndPayload = {
          type: 'trivia',
          netScore,
          correctAnswersCount,
          totalQuestions: questions.length,
        };
        onGameEnd(results);
      }
    }, FEEDBACK_DISPLAY_TIME_MS);
  }, [currentQuestionIndex, questions.length, onGameEnd, netScore, correctAnswersCount]);

  const processAnswer = useCallback((
    optionIndex: number, // Use TIMEOUT_SELECTED_INDEX for timeout
    isTimeoutFlag: boolean = false
  ) => {
    if (isAnswered) return;

    if (timerId !== null) {
      clearInterval(timerId);
      setTimerId(null);
    }
    setIsAnswered(true);

    const correctOptionIndex = currentQuestion.options.findIndex(opt => opt.isCorrect);
    let isCorrectOptionClicked = false;
    let currentScore = netScore;
    let currentCorrectAnswers = correctAnswersCount;

    if (isTimeoutFlag) {
      currentScore -= 1; // Penalty for timeout
      // isCorrectOptionClicked remains false
    } else {
      isCorrectOptionClicked = currentQuestion.options[optionIndex].isCorrect;
      if (isCorrectOptionClicked) {
        currentScore += 1; // Point for correct answer
        currentCorrectAnswers += 1;
      } else {
        // No change to netScore for incorrect click, only no point gained
      }
    }
    setNetScore(currentScore);
    setCorrectAnswersCount(currentCorrectAnswers);

    if (!isCorrectOptionClicked && !isTimeoutFlag) { // Shake if clicked wrong
        setQuestionContainerClass('anim-shake');
    } else if (isTimeoutFlag) { // Also shake on timeout to indicate an "incorrect" outcome
        setQuestionContainerClass('anim-shake');
    }

    setSelectedAnswerInfo({
      isCorrectResponse: isCorrectOptionClicked, 
      selectedIndex: isTimeoutFlag ? TIMEOUT_SELECTED_INDEX : optionIndex,
      correctIndex: correctOptionIndex,
      isTimeout: isTimeoutFlag,
    });

    proceedToNextPhase();

  }, [currentQuestion, isAnswered, netScore, correctAnswersCount, timerId, proceedToNextPhase]);


  // Effect for managing the timer
  useEffect(() => {
    if (!isAnswered && timerDuration > 0 && currentQuestion) { 
      setTimeLeft(timerDuration); 
      const newTimerId = setInterval(() => {
        setTimeLeft(prevTime => {
          if (prevTime <= 1) {
            clearInterval(newTimerId);
            processAnswer(TIMEOUT_SELECTED_INDEX, true); 
            return 0;
          }
          return prevTime - 1;
        });
      }, 1000);
      setTimerId(newTimerId as unknown as number); 

      return () => { 
        if (newTimerId) clearInterval(newTimerId);
      };
    } else if (isAnswered && timerId !== null) { 
        clearInterval(timerId);
        setTimerId(null);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentQuestionIndex, isAnswered, timerDuration, currentQuestion]);


  // Effect to reset state for new question
  useEffect(() => {
    setSelectedAnswerInfo(null);
    setIsAnswered(false);
    setQuestionContainerClass('anim-fade-in');
    setTimeLeft(timerDuration); 

    if (timerId !== null) {
        clearInterval(timerId);
        setTimerId(null);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentQuestionIndex, timerDuration]);


  if (!currentQuestion) {
    return <div className="text-center p-8 text-gray-700">Cargando pregunta...</div>;
  }

  const getButtonVariant = (index: number): 'correct' | 'incorrect' | 'option' => {
    if (!selectedAnswerInfo) return 'option';

    // If the selection was a timeout
    if (selectedAnswerInfo.isTimeout) {
      if (index === selectedAnswerInfo.correctIndex) return 'correct'; // Show correct answer on timeout
      return 'option'; // Other options remain normal but disabled
    }

    // If the user made a selection
    if (index === selectedAnswerInfo.selectedIndex) {
      return selectedAnswerInfo.isCorrectResponse ? 'correct' : 'incorrect';
    }
    // If user chose incorrectly, also highlight the correct answer
    if (!selectedAnswerInfo.isCorrectResponse && index === selectedAnswerInfo.correctIndex) {
      return 'correct';
    }
    return 'option';
  };

  const questionNumber = currentQuestionIndex + 1;

  return (
    <div className="flex flex-col min-h-[500px] justify-between relative pb-8 pt-28 bg-white/30 backdrop-blur-md rounded-xl shadow-xl">
      <div className="fixed top-0 left-1/2 transform -translate-x-1/2 w-full max-w-2xl p-4 bg-white/80 backdrop-blur-sm shadow-md z-10 rounded-t-xl">
        <div className="max-w-2xl mx-auto">
          <div className="flex justify-between items-center text-sm text-gray-700 mb-1">
            <div className="flex items-center gap-2">
                <p id="question-counter" className="font-semibold">
                    {isTraining ? `Pregunta: ${questionNumber}` : `Pregunta: ${questionNumber} de ${totalQuestions}`}
                </p>
                {isTraining && (
                    <button 
                        onClick={handleFinishTraining}
                        className="text-xs bg-red-100 text-red-600 px-2 py-1 rounded hover:bg-red-200 font-bold"
                    >
                        Terminar
                    </button>
                )}
            </div>
            <p id="score-counter" className="font-semibold text-blue-600">Puntaje Neto: {netScore}</p>
            {timerDuration > 0 && (
              <p id="timer-display" className={`font-semibold ${timeLeft <= 5 && timeLeft > 0 && !isAnswered ? 'text-red-500 anim-pulse' : 'text-gray-600'}`}>
                Tiempo: {timeLeft}s
              </p>
            )}
          </div>
          {!isTraining && <ProgressBar current={questionNumber} total={totalQuestions} />}
        </div>
      </div>

      <div className="px-4 sm:px-6 flex-grow flex flex-col justify-center">
        <div id="question-text-container" className={`my-6 text-center ${questionContainerClass}`}>
          <p className="text-xl md:text-2xl font-serif italic p-6 bg-white/60 rounded-xl shadow-md text-gray-700">
            "{currentQuestion.verse}"
          </p>
        </div>

        <div id="options-container" className="grid grid-cols-1 md:grid-cols-2 gap-3 sm:gap-4">
          {currentQuestion.options.map((option, index) => (
            <Button
              key={option.text + index} 
              onClick={() => processAnswer(index, false)}
              disabled={isAnswered}
              variant={getButtonVariant(index)}
              className={`w-full text-sm md:text-base anim-fade-in-up 
                          ${isAnswered && getButtonVariant(index) !== 'option' ? '' : isAnswered ? 'opacity-60' : ''}
                        `}
              style={{ animationDelay: `${index * 100}ms` }}
              aria-pressed={selectedAnswerInfo?.selectedIndex === index && !selectedAnswerInfo.isTimeout}
            >
              {option.text}
              {selectedAnswerInfo && index === selectedAnswerInfo.selectedIndex && !selectedAnswerInfo.isTimeout && (
                <span className="font-bold ml-2">{selectedAnswerInfo.isCorrectResponse ? '✓' : '✗'}</span>
              )}
            </Button>
          ))}
        </div>
         {selectedAnswerInfo?.isTimeout && (
            <p className="text-center text-red-600 font-semibold mt-4 anim-fade-in">¡Se acabó el tiempo! (-1 Pto)</p>
        )}
      </div>
    </div>
  );
};

export default GameScreen;

import React, { useState, useEffect, useCallback } from 'react';
import { OrderVerseItem, OrderVerseDifficultySetting, GameEndPayload, OrderVerseGameEndPayload } from '../types';
import Button from './Button';
import ProgressBar from './ProgressBar';

// Defines a word object that includes its original index to handle repeated words correctly
interface WordToken {
  text: string;
  originalIndex: number; // To distinguish identical words
  id: string; // Unique ID for React key prop: `word-${originalIndex}`
}

const FEEDBACK_DELAY_MS = 2500; // Time to show feedback before auto-advancing on incorrect

const OrderVerseScreen: React.FC<{
  items: OrderVerseItem[];
  difficulty: OrderVerseDifficultySetting;
  onGameEnd: (results: GameEndPayload) => void;
  isTraining?: boolean;
}> = ({ items, difficulty, onGameEnd, isTraining = false }) => {
  const [currentItemIndex, setCurrentItemIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [selectedWordTokens, setSelectedWordTokens] = useState<WordToken[]>([]);
  const [availableWordTokens, setAvailableWordTokens] = useState<WordToken[]>([]);
  const [feedback, setFeedback] = useState<{ message: string; type: 'correct' | 'incorrect' } | null>(null);
  const [isVerified, setIsVerified] = useState(false);
  const [isLoadingNext, setIsLoadingNext] = useState(false); // To disable buttons during transition

  const [timeLeft, setTimeLeft] = useState(difficulty.timerPerItem || 0);
  const [timerId, setTimerId] = useState<number | null>(null);

  const currentItem = items[currentItemIndex];
  const totalItems = items.length;

  const handleFinishTraining = useCallback(() => {
    // Finish immediately with current stats
    const results: OrderVerseGameEndPayload = {
        type: 'order_verse',
        score: score, 
        versesAttempted: currentItemIndex + (isVerified ? 1 : 0), // Count current if verified
        versesCorrect: score, 
      };
      onGameEnd(results);
  }, [score, currentItemIndex, isVerified, onGameEnd]);

  const setupCurrentVerse = useCallback(() => {
    if (!currentItem) return;
    setSelectedWordTokens([]);
    setAvailableWordTokens(
      currentItem.words.map((word, index) => ({
        text: word,
        originalIndex: currentItem.correctWordOrder.findIndex((w, i) => w === word && !currentItem.words.slice(0, index).some((sw, si) => sw === word && currentItem.correctWordOrder.findIndex((cw,ci) => cw === sw) === i )),
        id: `word-${index}` 
      }))
    );
    setFeedback(null);
    setIsVerified(false);
    setIsLoadingNext(false);
    setTimeLeft(difficulty.timerPerItem || 0);
  }, [currentItem, difficulty.timerPerItem]);

  useEffect(() => {
    setupCurrentVerse();
  }, [currentItemIndex, items, setupCurrentVerse]);

  // Timer Effect
  useEffect(() => {
    if (timerId) {
      clearInterval(timerId);
      setTimerId(null);
    }

    if (!isVerified && difficulty.timerPerItem && difficulty.timerPerItem > 0 && currentItem) {
      setTimeLeft(difficulty.timerPerItem); // Reset time for new item/attempt
      const newTimerId = setInterval(() => {
        setTimeLeft(prevTime => {
          if (prevTime <= 1) {
            clearInterval(newTimerId);
            setTimerId(null);
            setIsVerified(true);
            setFeedback({ 
              message: `¡Se acabó el tiempo! El orden correcto era: "${currentItem.correctWordOrder.join(' ')}"`, 
              type: 'incorrect' 
            });
            setIsLoadingNext(false); // Enable "Continuar"
            return 0;
          }
          return prevTime - 1;
        });
      }, 1000);
      setTimerId(newTimerId as unknown as number);
    }

    return () => {
      if (timerId) clearInterval(timerId);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentItemIndex, isVerified, difficulty.timerPerItem, currentItem]);


  const handleSelectWord = (tokenToSelect: WordToken) => {
    if (isVerified || isLoadingNext) return;
    setSelectedWordTokens(prev => [...prev, tokenToSelect]);
    setAvailableWordTokens(prev => prev.filter(token => token.id !== tokenToSelect.id));
  };

  const handleDeselectWord = (tokenToDeselect: WordToken) => {
    if (isVerified || isLoadingNext) return;
    setAvailableWordTokens(prev => [...prev, tokenToDeselect]); 
    setSelectedWordTokens(prev => prev.filter(token => token.id !== tokenToDeselect.id));
  };

  const handleVerifyOrder = () => {
    if (selectedWordTokens.length === 0 || isLoadingNext) return;
    setIsLoadingNext(true); 

    if (timerId) { // Clear active timer if user submits before timeout
      clearInterval(timerId);
      setTimerId(null);
    }

    const playerOrderText = selectedWordTokens.map(token => token.text).join(' ');
    const correctOrderText = currentItem.correctWordOrder.join(' ');

    if (playerOrderText === correctOrderText) {
      setScore(prev => prev + 1);
      setFeedback({ message: "¡Correcto!", type: 'correct' });
      setIsVerified(true);
      setTimeout(() => proceedToNextItem(true), 1200); 
    } else {
      setFeedback({ 
        message: `Incorrecto. El orden correcto era: "${correctOrderText}"`, 
        type: 'incorrect' 
      });
      setIsVerified(true); 
      setIsLoadingNext(false); 
    }
  };

  const proceedToNextItem = (wasCorrect: boolean) => {
    setIsLoadingNext(true);
    if (timerId) {
      clearInterval(timerId);
      setTimerId(null);
    }

    if (currentItemIndex < totalItems - 1) {
      setCurrentItemIndex(prev => prev + 1);
      // setupCurrentVerse will be called by useEffect
    } else {
      // Game End
      const finalPayload: OrderVerseGameEndPayload = {
        type: 'order_verse',
        score: score, 
        versesAttempted: totalItems,
        versesCorrect: score, 
      };
      onGameEnd(finalPayload);
    }
  };


  if (!currentItem) {
    return <div className="text-center p-8 text-gray-700">Cargando desafío de orden...</div>;
  }

  const itemNumber = currentItemIndex + 1;

  return (
    <div className="flex flex-col min-h-[550px] justify-between relative pt-24 pb-6 bg-white/30 backdrop-blur-md rounded-xl shadow-xl">
      {/* Header */}
      <div className="fixed top-0 left-1/2 transform -translate-x-1/2 w-full max-w-2xl px-4 py-3 bg-white/80 backdrop-blur-sm shadow-md z-20 rounded-t-xl">
        <div className="max-w-2xl mx-auto">
          <div className="flex justify-between items-center text-xs sm:text-sm text-gray-700 mb-1">
             <div className="flex items-center gap-2">
                <p id="item-counter" className="font-semibold">
                    {isTraining ? `Ítem: ${itemNumber}` : `Ítem: ${itemNumber} de ${totalItems}`}
                </p>
                {isTraining && (
                    <button 
                        onClick={handleFinishTraining}
                        className="text-xs bg-red-100 text-red-600 px-2 py-1 rounded hover:bg-red-200 font-bold"
                    >
                        Terminar
                    </button>
                )}
            </div>
            <p id="score-counter" className="font-semibold text-blue-600">Puntaje: {score}</p>
            {difficulty.timerPerItem && difficulty.timerPerItem > 0 && (
              <p id="timer-display" className={`font-semibold ${timeLeft <= 5 && timeLeft > 0 && !isVerified ? 'text-red-500 anim-pulse' : 'text-gray-600'}`}>
                Tiempo: {timeLeft}s
              </p>
            )}
          </div>
          {!isTraining && <ProgressBar current={itemNumber} total={totalItems} />}
        </div>
      </div>

      {/* Game Area */}
      <div className="px-3 sm:px-5 flex-grow flex flex-col items-center">
        <p className="text-center text-lg font-semibold text-gray-700 mt-2 mb-3">
          Ordena el versículo: <span className="font-bold text-amber-600">{currentItem.reference}</span>
        </p>

        {/* Selected Words Area (Top) */}
        <div 
          className="w-full min-h-[100px] sm:min-h-[120px] bg-white/50 border-2 border-dashed border-amber-400 rounded-lg p-2 sm:p-3 mb-3 sm:mb-4 flex flex-wrap gap-1.5 sm:gap-2 content-start"
          aria-label="Área de palabras seleccionadas"
        >
          {selectedWordTokens.map((token) => (
            <button
              key={token.id}
              onClick={() => handleDeselectWord(token)}
              disabled={isVerified || isLoadingNext}
              className="bg-sky-500 text-white px-2.5 py-1.5 sm:px-3 sm:py-2 text-sm sm:text-base rounded-md shadow hover:bg-sky-600 focus:outline-none focus:ring-2 focus:ring-sky-400 disabled:opacity-70 disabled:cursor-not-allowed transition-all"
            >
              {token.text}
            </button>
          ))}
          {selectedWordTokens.length === 0 && !isVerified && (
            <p className="text-gray-400 text-sm italic self-center mx-auto">Selecciona palabras de abajo.</p>
          )}
        </div>

        {/* Feedback Area */}
        {feedback && (
          <div className={`w-full p-2.5 sm:p-3 mb-3 text-center rounded-md shadow-md text-sm sm:text-base anim-fade-in ${feedback.type === 'correct' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}
            role="alert"
          >
            {feedback.message}
          </div>
        )}

        {/* Available Words Area (Bottom) */}
        {!isVerified && (
          <div 
            className="w-full min-h-[120px] sm:min-h-[150px] bg-white/40 border-2 border-gray-300 rounded-lg p-2 sm:p-3 mb-4 flex flex-wrap gap-1.5 sm:gap-2 content-start justify-center"
            aria-label="Área de palabras disponibles para seleccionar"
            >
            {availableWordTokens.map((token) => (
              <button
                key={token.id}
                onClick={() => handleSelectWord(token)}
                disabled={isLoadingNext}
                className="bg-amber-400 text-gray-800 px-2.5 py-1.5 sm:px-3 sm:py-2 text-sm sm:text-base rounded-md shadow hover:bg-amber-500 focus:outline-none focus:ring-2 focus:ring-amber-300 disabled:opacity-70 disabled:cursor-not-allowed transition-all"
              >
                {token.text}
              </button>
            ))}
            {availableWordTokens.length === 0 && selectedWordTokens.length > 0 && (
                 <p className="text-gray-400 text-sm italic self-center mx-auto">¡Todas las palabras usadas! Verifica tu orden.</p>
            )}
             {availableWordTokens.length === 0 && selectedWordTokens.length === 0 && ( // Should not happen if item has words
                 <p className="text-gray-400 text-sm italic self-center mx-auto">No hay palabras disponibles.</p>
            )}
          </div>
        )}
      </div>

      {/* Action Button */}
      <div className="px-3 sm:px-5 mt-auto">
        {isVerified ? (
          <Button
            onClick={() => proceedToNextItem(feedback?.type === 'correct')}
            variant="primary"
            className="w-full text-lg"
            disabled={isLoadingNext}
            aria-label={currentItemIndex < totalItems -1 ? "Siguiente versículo" : "Ver resultados finales"}
          >
            {isLoadingNext ? "Cargando..." : (currentItemIndex < totalItems - 1 ? (feedback?.type === 'correct' ? "Siguiente" : "Continuar") : "Finalizar")}
          </Button>
        ) : (
          <Button
            onClick={handleVerifyOrder}
            variant="primary"
            className="w-full text-lg"
            disabled={selectedWordTokens.length === 0 || isLoadingNext}
            aria-label="Verificar el orden de las palabras seleccionadas"
          >
            {isLoadingNext ? "Verificando..." : "Verificar Orden"}
          </Button>
        )}
      </div>
    </div>
  );
};

export default OrderVerseScreen;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ReciteVerseItem, ReciteVerseDifficultySetting, GameEndPayload, ReciteVerseGameEndPayload, VisibleLettersMode } from '../types';
import Button from './Button';
import ProgressBar from './ProgressBar';

const FEEDBACK_AUTO_ADVANCE_MS = 2500; // Time to show feedback before auto-advancing (if correct)

interface CharInputProps {
  char: string;
  wordIndex: number;
  letterIndex: number;
  value: string;
  onChange: (wordIndex: number, letterIndex: number, value: string) => void;
  onKeyDown: (e: React.KeyboardEvent<HTMLInputElement>, wordIndex: number, letterIndex: number) => void;
  isFocused: boolean;
  inputRef: React.RefObject<HTMLInputElement>;
  disabled: boolean;
  visibleLettersMode: VisibleLettersMode;
  isFirstLetter: boolean;
  isLastLetter: boolean;
}

const CharInput: React.FC<CharInputProps> = ({
  char, wordIndex, letterIndex, value, onChange, onKeyDown, isFocused, inputRef, disabled,
  visibleLettersMode, isFirstLetter, isLastLetter
}) => {
  let displayChar: string | null = null;
  // let isInputDisabled = disabled; // This was here, but disabled prop already handles it

  if (visibleLettersMode === 'firstAndLast') {
    if (isFirstLetter || isLastLetter) displayChar = char;
  } else if (visibleLettersMode === 'firstOnly') {
    if (isFirstLetter) displayChar = char;
  }

  const isEffectivelyFixed = displayChar !== null;

  useEffect(() => {
    if (isFocused && inputRef.current && !isEffectivelyFixed) {
      inputRef.current.focus();
    }
  }, [isFocused, inputRef, isEffectivelyFixed]);

  if (isEffectivelyFixed) {
    return (
      <span className="w-6 h-8 sm:w-7 sm:h-9 md:w-8 md:h-10 flex items-center justify-center bg-gray-200/70 border border-gray-300 rounded text-sm sm:text-base font-medium text-gray-700 select-none">
        {displayChar}
      </span>
    );
  }

  return (
    <input
      ref={inputRef}
      type="text"
      maxLength={1}
      value={value}
      onChange={(e) => onChange(wordIndex, letterIndex, e.target.value)}
      onKeyDown={(e) => onKeyDown(e, wordIndex, letterIndex)}
      disabled={disabled} // Use the passed disabled prop directly
      className="w-6 h-8 sm:w-7 sm:h-9 md:w-8 md:h-10 text-center border border-gray-400 rounded focus:border-amber-500 focus:ring-1 focus:ring-amber-500 text-sm sm:text-base font-medium transition-colors disabled:bg-gray-100 disabled:text-gray-400 disabled:cursor-not-allowed"
      aria-label={`Letra ${letterIndex + 1} de la palabra ${wordIndex + 1}`}
    />
  );
};


const ReciteVerseScreen: React.FC<{
  items: ReciteVerseItem[];
  difficultySettings: ReciteVerseDifficultySetting;
  onGameEnd: (results: GameEndPayload) => void;
  isTraining?: boolean;
}> = ({ items, difficultySettings, onGameEnd, isTraining = false }) => {
  const [currentItemIndex, setCurrentItemIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [userInputWords, setUserInputWords] = useState<string[][]>([]);
  const [focusCoordinates, setFocusCoordinates] = useState<{ wordIndex: number; letterIndex: number } | null>(null);
  const [feedback, setFeedback] = useState<{ message: string; type: 'correct' | 'incorrect' } | null>(null);
  const [isVerified, setIsVerified] = useState(false);
  const [isLoadingNext, setIsLoadingNext] = useState(false);

  const [timeLeft, setTimeLeft] = useState(difficultySettings.timerPerItem || 0);
  const [timerId, setTimerId] = useState<number | null>(null);

  const inputRefs = useRef<Array<Array<React.RefObject<HTMLInputElement> | null>>>([]);

  const currentItem = items[currentItemIndex];
  const totalItems = items.length;

  const handleFinishTraining = useCallback(() => {
    // Finish immediately with current stats
    const results: ReciteVerseGameEndPayload = {
        type: 'recite_verse',
        score: score, 
        versesAttempted: currentItemIndex + (isVerified ? 1 : 0),
        versesCorrect: score, 
      };
      onGameEnd(results);
  }, [score, currentItemIndex, isVerified, onGameEnd]);

  const initializeInputsAndFocus = useCallback(() => {
    if (!currentItem) return;
    const newUserInputWords = currentItem.words.map(word => Array(word.length).fill(''));
    setUserInputWords(newUserInputWords);

    inputRefs.current = currentItem.words.map(word =>
      Array(word.length).fill(null).map(() => React.createRef<HTMLInputElement>())
    );

    let firstEditableFocus: { wordIndex: number; letterIndex: number } | null = null;
    for (let wIdx = 0; wIdx < currentItem.words.length; wIdx++) {
      for (let lIdx = 0; lIdx < currentItem.words[wIdx].length; lIdx++) {
        const word = currentItem.words[wIdx];
        const isFirst = lIdx === 0;
        const isLast = lIdx === word.length - 1;
        let isFixed = false;
        if (difficultySettings.visibleLettersMode === 'firstAndLast' && (isFirst || isLast)) isFixed = true;
        if (difficultySettings.visibleLettersMode === 'firstOnly' && isFirst) isFixed = true;

        if (!isFixed) {
          firstEditableFocus = { wordIndex: wIdx, letterIndex: lIdx };
          break;
        }
      }
      if (firstEditableFocus) break;
    }
    setFocusCoordinates(firstEditableFocus);
    setFeedback(null);
    setIsVerified(false);
    setIsLoadingNext(false);
    setTimeLeft(difficultySettings.timerPerItem || 0);
  }, [currentItem, difficultySettings.visibleLettersMode, difficultySettings.timerPerItem]);

  useEffect(() => {
    initializeInputsAndFocus();
  }, [currentItemIndex, items, initializeInputsAndFocus]);

  // Timer Effect
  useEffect(() => {
    if (timerId) {
        clearInterval(timerId);
        setTimerId(null);
    }

    if (!isVerified && difficultySettings.timerPerItem && difficultySettings.timerPerItem > 0 && currentItem) {
        setTimeLeft(difficultySettings.timerPerItem);
        const newTimerId = setInterval(() => {
            setTimeLeft(prevTime => {
                if (prevTime <= 1) {
                    clearInterval(newTimerId);
                    setTimerId(null);
                    setIsVerified(true);
                    setFeedback({ 
                        message: `¡Se acabó el tiempo! El texto correcto es: "${currentItem.fullText}"`, 
                        type: 'incorrect' 
                    });
                    setIsLoadingNext(false);
                    return 0;
                }
                return prevTime - 1;
            });
        }, 1000);
        setTimerId(newTimerId as unknown as number);
    }

    return () => {
        if (timerId) clearInterval(timerId);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentItemIndex, isVerified, difficultySettings.timerPerItem, currentItem]);


  const moveToFocus = (wordIdx: number, letterIdx: number, direction: 'next' | 'prev') => {
    if (!currentItem) return;

    const findNextEditable = (w: number, l: number): { wordIndex: number; letterIndex: number } | null => {
      let currentW = w;
      let currentL = l + 1; // Start checking from next position

      for (let wIdx = currentW; wIdx < currentItem.words.length; wIdx++) {
        const word = currentItem.words[wIdx];
        // If starting a new word, reset letter index
        if (wIdx > currentW) currentL = 0; 

        for (let lIdx = currentL; lIdx < word.length; lIdx++) {
          const isFirst = lIdx === 0;
          const isLast = lIdx === word.length - 1;
          let isFixed = false;
          if (difficultySettings.visibleLettersMode === 'firstAndLast' && (isFirst || isLast)) isFixed = true;
          if (difficultySettings.visibleLettersMode === 'firstOnly' && isFirst) isFixed = true;
          if (!isFixed) return { wordIndex: wIdx, letterIndex: lIdx };
        }
        currentL = 0; // Ensure next word starts from 0
      }
      return null; 
    };

    const findPrevEditable = (w: number, l: number): { wordIndex: number; letterIndex: number } | null => {
      let currentW = w;
      let currentL = l - 1; // Start checking from previous position

      for (let wIdx = currentW; wIdx >= 0; wIdx--) {
        const word = currentItem.words[wIdx];
         // If starting a new word (moving backwards), set letter index to end of that word
        if (wIdx < currentW) currentL = currentItem.words[wIdx].length - 1;

        for (let lIdx = currentL; lIdx >= 0; lIdx--) {
          const isFirst = lIdx === 0;
          const isLast = lIdx === word.length - 1;
          let isFixed = false;
          if (difficultySettings.visibleLettersMode === 'firstAndLast' && (isFirst || isLast)) isFixed = true;
          if (difficultySettings.visibleLettersMode === 'firstOnly' && isFirst) isFixed = true;
          if (!isFixed) return { wordIndex: wIdx, letterIndex: lIdx };
        }
        currentL = -1; // Ensure prev word checks from its end
      }
      return null; 
    };

    if (direction === 'next') {
      const nextFocus = findNextEditable(wordIdx, letterIdx);
      if (nextFocus) setFocusCoordinates(nextFocus);
    } else { // prev
      const prevFocus = findPrevEditable(wordIdx, letterIdx);
      if (prevFocus) setFocusCoordinates(prevFocus);
    }
  };

  const handleInputChange = (wordIdx: number, letterIdx: number, value: string) => {
    if (isVerified || isLoadingNext) return;
    const char = value.slice(-1).toLowerCase(); // Normalize to lowercase for consistency
    setUserInputWords(prev => {
      const newInputs = prev.map(wordArr => [...wordArr]);
      newInputs[wordIdx][letterIdx] = char;
      return newInputs;
    });
    if (char) { 
      moveToFocus(wordIdx, letterIdx, 'next');
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>, wordIdx: number, letterIdx: number) => {
    if (isVerified || isLoadingNext) return;
    if (e.key === 'Backspace') {
      e.preventDefault();
      const currentVal = userInputWords[wordIdx][letterIdx];
      setUserInputWords(prev => {
        const newInputs = prev.map(wordArr => [...wordArr]);
        newInputs[wordIdx][letterIdx] = ''; 
        return newInputs;
      });
      if (!currentVal) { 
        moveToFocus(wordIdx, letterIdx, 'prev');
      } else { 
        setFocusCoordinates({ wordIndex: wordIdx, letterIndex: letterIdx }); 
      }
    } else if (e.key === 'ArrowLeft') {
        e.preventDefault();
        moveToFocus(wordIdx, letterIdx, 'prev');
    } else if (e.key === 'ArrowRight') {
        e.preventDefault();
        moveToFocus(wordIdx, letterIdx, 'next');
    } else if (e.key === 'Enter') {
        e.preventDefault();
        if (!isVerified) verifyVerse();
    }
  };

  const verifyVerse = () => {
    if (isLoadingNext || isVerified) return;
    setIsLoadingNext(true);

    if (timerId) {
      clearInterval(timerId);
      setTimerId(null);
    }

    const userAnswer = userInputWords.map(wordArr => wordArr.join('')).join(' ').trim();
    const correctAnswer = currentItem.fullText.trim();

    // Normalize by removing punctuation for comparison, then compare lowercase
    const normalizeText = (text: string) => 
        text.toLowerCase().replace(/[.,;:!?"'-]/g, '').replace(/\s+/g, ' ');

    const normalizedUserAnswer = normalizeText(userAnswer);
    const normalizedCorrectAnswer = normalizeText(correctAnswer);

    if (normalizedUserAnswer === normalizedCorrectAnswer) {
      setScore(prev => prev + 1);
      setFeedback({ message: "¡Correcto!", type: 'correct' });
      setIsVerified(true);
      setTimeout(() => proceedToNextItem(true), FEEDBACK_AUTO_ADVANCE_MS);
    } else {
      setFeedback({ message: `Incorrecto. El texto correcto es: "${correctAnswer}"`, type: 'incorrect' });
      setIsVerified(true);
      setIsLoadingNext(false); 
    }
  };

  const proceedToNextItem = (wasCorrect: boolean) => {
    setIsLoadingNext(true);
     if (timerId) {
      clearInterval(timerId);
      setTimerId(null);
    }

    if (currentItemIndex < totalItems - 1) {
      setCurrentItemIndex(prev => prev + 1);
      // initializeInputsAndFocus will be called by useEffect
    } else {
      const finalPayload: ReciteVerseGameEndPayload = {
        type: 'recite_verse',
        score: score, 
        versesAttempted: totalItems,
        versesCorrect: score, 
      };
      onGameEnd(finalPayload);
    }
  };

  if (!currentItem || userInputWords.length === 0) {
    return <div className="text-center p-8 text-gray-700">Cargando desafío de recitación...</div>;
  }

  const itemNumber = currentItemIndex + 1;

  return (
    <div className="flex flex-col min-h-[550px] justify-between relative pt-24 pb-6 bg-white/30 backdrop-blur-md rounded-xl shadow-xl">
      {/* Header */}
      <div className="fixed top-0 left-1/2 transform -translate-x-1/2 w-full max-w-2xl px-4 py-3 bg-white/80 backdrop-blur-sm shadow-md z-20 rounded-t-xl">
        <div className="max-w-2xl mx-auto">
          <div className="flex justify-between items-center text-xs sm:text-sm text-gray-700 mb-1">
             <div className="flex items-center gap-2">
                <p id="item-counter" className="font-semibold">
                    {isTraining ? `Ítem: ${itemNumber}` : `Ítem: ${itemNumber} de ${totalItems}`}
                </p>
                {isTraining && (
                    <button 
                        onClick={handleFinishTraining}
                        className="text-xs bg-red-100 text-red-600 px-2 py-1 rounded hover:bg-red-200 font-bold"
                    >
                        Terminar
                    </button>
                )}
            </div>
            <p id="score-counter" className="font-semibold text-blue-600">Puntaje: {score}</p>
            {difficultySettings.timerPerItem && difficultySettings.timerPerItem > 0 && (
              <p id="timer-display" className={`font-semibold ${timeLeft <= 5 && timeLeft > 0 && !isVerified ? 'text-red-500 anim-pulse' : 'text-gray-600'}`}>
                Tiempo: {timeLeft}s
              </p>
            )}
          </div>
          {!isTraining && <ProgressBar current={itemNumber} total={totalItems} />}
        </div>
      </div>

      {/* Game Area */}
      <div className="px-3 sm:px-5 flex-grow flex flex-col items-center w-full">
        <p className="text-center text-lg font-semibold text-gray-700 mt-2 mb-4">
          Recita el versículo: <span className="font-bold text-amber-600">{currentItem.reference}</span>
        </p>

        {/* Verse Input Area */}
        <div className="w-full bg-white/50 p-3 sm:p-4 rounded-lg shadow flex flex-wrap justify-center gap-x-1.5 sm:gap-x-2 gap-y-2 mb-4"
             aria-label="Área de entrada del versículo">
          {currentItem.words.map((word, wordIdx) => (
            <div key={`word-${wordIdx}`} className="flex items-center gap-px sm:gap-0.5">
              {word.split('').map((char, letterIdx) => (
                <CharInput
                  key={`char-${wordIdx}-${letterIdx}`}
                  char={char}
                  wordIndex={wordIdx}
                  letterIndex={letterIdx}
                  value={userInputWords[wordIdx]?.[letterIdx] || ''}
                  onChange={handleInputChange}
                  onKeyDown={handleKeyDown}
                  isFocused={focusCoordinates?.wordIndex === wordIdx && focusCoordinates?.letterIndex === letterIdx}
                  inputRef={inputRefs.current[wordIdx]?.[letterIdx]!}
                  disabled={isVerified || isLoadingNext}
                  visibleLettersMode={difficultySettings.visibleLettersMode}
                  isFirstLetter={letterIdx === 0}
                  isLastLetter={letterIdx === word.length - 1}
                />
              ))}
            </div>
          ))}
        </div>

        {/* Feedback Area */}
        {feedback && (
          <div className={`w-full p-2.5 sm:p-3 mb-3 text-center rounded-md shadow-md text-sm sm:text-base anim-fade-in ${feedback.type === 'correct' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}
            role="alert"
          >
            {feedback.message}
          </div>
        )}
      </div>

      {/* Action Button */}
      <div className="px-3 sm:px-5 mt-auto">
        {isVerified ? (
          <Button
            onClick={() => proceedToNextItem(feedback?.type === 'correct')}
            variant="primary"
            className="w-full text-lg"
            disabled={isLoadingNext}
            aria-label={currentItemIndex < totalItems -1 ? "Siguiente versículo" : "Ver resultados finales"}
          >
            {isLoadingNext ? "Cargando..." : (currentItemIndex < totalItems - 1 ? (feedback?.type === 'correct' ? "Siguiente" : "Continuar") : "Finalizar")}
          </Button>
        ) : (
          <Button
            onClick={verifyVerse}
            variant="primary"
            className="w-full text-lg"
            disabled={isLoadingNext}
            aria-label="Verificar el versículo recitado"
          >
            {isLoadingNext ? "Verificando..." : "Verificar Versículo"}
          </Button>
        )}
      </div>
    </div>
  );
};

export default ReciteVerseScreen;

import React, { useState, useEffect, useCallback } from 'react';
import { MemoryCardData, MemoryDifficultySetting, GameEndPayload } from '../types';
import MemoryCard from './MemoryCard';
import Button from './Button'; // For a potential "Quit" button

const MISMATCH_DELAY_MS = 1000;

interface MemoryGameScreenProps {
  cards: MemoryCardData[];
  difficulty: MemoryDifficultySetting;
  onGameEnd: (results: GameEndPayload) => void;
  isTraining?: boolean;
}

const MemoryGameScreen: React.FC<MemoryGameScreenProps> = ({ cards, difficulty, onGameEnd, isTraining = false }) => {
  const [gameCards, setGameCards] = useState<MemoryCardData[]>([]);
  const [flippedIndices, setFlippedIndices] = useState<number[]>([]);
  const [moves, setMoves] = useState(0);
  const [pairsFound, setPairsFound] = useState(0);
  const [isChecking, setIsChecking] = useState(false); // To prevent clicks during pair check or mismatch delay
  const [gridColsClass, setGridColsClass] = useState('grid-cols-4'); // Default

  useEffect(() => {
    // Initialize game cards based on props
    setGameCards(cards.map(card => ({ ...card, isFlipped: false, isMatched: false })));
    setFlippedIndices([]);
    setMoves(0);
    setPairsFound(0);
    setIsChecking(false);

    // Set grid columns based on difficulty
    // Tailwind needs full class names, so we can't just do `grid-cols-${difficulty.grid.cols}` directly in className
    switch (difficulty.grid.cols) {
        case 3: setGridColsClass('grid-cols-3'); break;
        case 4: setGridColsClass('grid-cols-4'); break;
        case 5: setGridColsClass('grid-cols-5'); break;
        case 6: setGridColsClass('grid-cols-6'); break;
        default: setGridColsClass('grid-cols-4'); // Fallback
    }

  }, [cards, difficulty]);

  const handleFinishTraining = () => {
      onGameEnd({ type: 'memory', moves, totalPairs: pairsFound }); // Report what has been found so far
  };

  const handleCardFlipAttempt = (index: number) => { // Renamed from handleCardClick for clarity, as it's passed to MemoryCard
    if (isChecking || gameCards[index].isFlipped || gameCards[index].isMatched || flippedIndices.length >= 2) {
      return;
    }

    const newFlippedIndices = [...flippedIndices, index];
    setFlippedIndices(newFlippedIndices);

    setGameCards(prevCards =>
      prevCards.map((card, i) => (i === index ? { ...card, isFlipped: true } : card))
    );

    if (newFlippedIndices.length === 2) {
      setIsChecking(true); // Start checking phase
      setMoves(prevMoves => prevMoves + 1);
      // Check for match after a short delay to allow flip animation
      setTimeout(checkForMatch, 500, newFlippedIndices);
    }
  };

  const checkForMatch = useCallback((indicesToCheck: number[]) => {
    const [firstIndex, secondIndex] = indicesToCheck;
    const card1 = gameCards[firstIndex];
    const card2 = gameCards[secondIndex];

    if (card1.pairId === card2.pairId) {
      // Match found
      setGameCards(prevCards =>
        prevCards.map(card =>
          card.pairId === card1.pairId ? { ...card, isMatched: true, isFlipped: true } : card
        )
      );
      setPairsFound(prevPairs => {
        const newPairsFound = prevPairs + 1;
        if (newPairsFound === difficulty.pairs) {
          // Game Over
          setTimeout(() => { // Delay slightly to show final match
            onGameEnd({ type: 'memory', moves, totalPairs: difficulty.pairs });
          }, 500);
        }
        return newPairsFound;
      });
      setFlippedIndices([]);
      setIsChecking(false); // End checking phase
    } else {
      // No match
      setTimeout(() => {
        setGameCards(prevCards =>
          prevCards.map((card, i) =>
            i === firstIndex || i === secondIndex ? { ...card, isFlipped: false } : card
          )
        );
        setFlippedIndices([]);
        setIsChecking(false); // End checking phase
      }, MISMATCH_DELAY_MS);
    }
  }, [gameCards, difficulty.pairs, onGameEnd, moves]);


  if (gameCards.length === 0) {
    return <div className="text-center p-8 text-gray-700">Cargando juego de memoria...</div>;
  }

  return (
    <div className="flex flex-col min-h-[500px] justify-start relative p-4 bg-white/30 backdrop-blur-md rounded-xl shadow-xl">
      <div className="w-full mb-4 p-3 bg-white/70 backdrop-blur-sm rounded-lg shadow sticky top-0 z-10 flex flex-col sm:flex-row justify-between items-center gap-2">
        <div className="flex justify-between items-center text-sm sm:text-base text-gray-700 w-full sm:w-auto gap-4">
          <p className="font-semibold">Movimientos: <span className="text-amber-600">{moves}</span></p>
          <p className="font-semibold">Pares Encontrados: <span className="text-green-600">{pairsFound}</span> / {difficulty.pairs}</p>
        </div>
        {isTraining && (
            <button 
                onClick={handleFinishTraining}
                className="text-xs sm:text-sm bg-red-100 text-red-600 px-3 py-1.5 rounded-lg hover:bg-red-200 font-bold shadow-sm transition-colors"
            >
                Terminar Entrenamiento
            </button>
        )}
      </div>

      <div className={`grid ${gridColsClass} gap-2 sm:gap-3 flex-grow`}>
        {gameCards.map((card, index) => (
          <MemoryCard
            key={card.id}
            card={card}
            onAttemptFlip={() => handleCardFlipAttempt(index)}
            isGameInteractionDisabled={isChecking && !card.isFlipped} // Disable non-flipped cards during check for game interaction
          />
        ))}
      </div>
    </div>
  );
};

