const App: React.FC = () => {
  const [currentScreen, setCurrentScreen] = useState<GameScreenState>(GameScreenState.Home);
  const [selectedGameMode, setSelectedGameMode] = useState<GameMode>(GameMode.TRIVIA);
  const [activeGameSettings, setActiveGameSettings] = useState<DifficultySetting | MemoryDifficultySetting | OrderVerseDifficultySetting | ReciteVerseDifficultySetting | TimelineDifficultySetting | BookSortDifficultySetting | null>(null);
  const [activeCategory, setActiveCategory] = useState<TriviaCategory | undefined>(CATEGORIES[0]);

  const [gameResults, setGameResults] = useState<GameEndPayload | null>(null);

  const [triviaQuestions, setTriviaQuestions] = useState<TriviaQuestion[]>([]);
  const [memoryCards, setMemoryCards] = useState<MemoryCardData[]>([]);
  const [orderVerseItems, setOrderVerseItems] = useState<OrderVerseItem[]>([]);
  const [reciteVerseItems, setReciteVerseItems] = useState<ReciteVerseItem[]>([]);
  const [timelineItems, setTimelineItems] = useState<TimelineItemData[]>([]);
  const [bookSortItems, setBookSortItems] = useState<BookData[]>([]);

  const [viewAnimation, setViewAnimation] = useState('anim-fade-in');
  const [isLoading, setIsLoading] = useState(false);
  const [appReady, setAppReady] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      setAppReady(true);
    }, 2800); 
    return () => clearTimeout(timer);
  }, []);

  const navigateTo = useCallback((newScreen: GameScreenState) => {
    setViewAnimation('anim-fade-out');
    setTimeout(() => {
      setCurrentScreen(newScreen);
      setViewAnimation('anim-fade-in');
      setIsLoading(false); 
    }, 300); 
  }, []);

  const prepareTriviaQuestions = useCallback((category: TriviaCategory, difficulty: DifficultySetting): boolean => {
    if (TRIVIA_SOURCE_DATA.length < MINIMUM_SOURCE_DATA_ITEMS_TRIVIA) {
        alert(`No hay suficientes datos base (${TRIVIA_SOURCE_DATA.length}) para Trivia.`);
        return false;
    }
    let candidateBaseItems: SourceDataItem[] = category === TriviaCategory.ALL ? 
        [...TRIVIA_SOURCE_DATA] : 
        TRIVIA_SOURCE_DATA.filter(item => item.category === category);

    const numQuestionsToSelect = difficulty.questions === -1 ? candidateBaseItems.length : difficulty.questions;

    if (candidateBaseItems.length === 0) {
      alert(`No hay preguntas de trivia disponibles para la categoría "${category}".`);
      return false;
    }
    const actualNumQuestions = Math.min(candidateBaseItems.length, numQuestionsToSelect);
    const selectedBaseItems = shuffleArray(candidateBaseItems).slice(0, actualNumQuestions);

    const newGameQuestions: TriviaQuestion[] = selectedBaseItems.map((baseItem) => {
      const correctOption: TriviaOption = { text: baseItem.correctAnswer, isCorrect: true };
      let incorrectAnswersPool = TRIVIA_SOURCE_DATA
        .filter(item => item.id !== baseItem.id) 
        .map(item => item.correctAnswer);

      incorrectAnswersPool = Array.from(new Set(incorrectAnswersPool.filter(ans => ans !== baseItem.correctAnswer)));
      const numberOfIncorrectOptionsToPick = Math.min(3, incorrectAnswersPool.length); 
      const incorrectOptionsTexts = shuffleArray(incorrectAnswersPool).slice(0, numberOfIncorrectOptionsToPick);
      const incorrectOptions: TriviaOption[] = incorrectOptionsTexts.map(text => ({ text, isCorrect: false }));
      const allOptions = shuffleArray([correctOption, ...incorrectOptions]);

      return {
        id: baseItem.id,
        verse: baseItem.text,
        options: allOptions,
        category: baseItem.category,
      };
    });

    const validGameQuestions = newGameQuestions.filter(q => q.options.length >= 2);
    if (validGameQuestions.length === 0) return false;
    setTriviaQuestions(validGameQuestions);
    return true;
  }, []);

  const prepareMemoryCards = useCallback((difficulty: MemoryDifficultySetting, category?: TriviaCategory): boolean => {
    const numPairs = difficulty.pairs;
    let sourceForMemory = TRIVIA_SOURCE_DATA;

    if (category && category !== TriviaCategory.ALL) {
      sourceForMemory = TRIVIA_SOURCE_DATA.filter(item => item.category === category);
    }
    if (sourceForMemory.length < numPairs) {
        alert("No hay suficientes datos para memoria.");
        return false;
    }
    const selectedItems = shuffleArray([...sourceForMemory]).slice(0, numPairs);

    let newMemoryCards: MemoryCardData[] = [];
    selectedItems.forEach((item) => {
      newMemoryCards.push({ id: `${item.id}_text`, pairId: item.id, content: item.text, isFlipped: false, isMatched: false });
      newMemoryCards.push({ id: `${item.id}_ref`, pairId: item.id, content: item.correctAnswer, isFlipped: false, isMatched: false });
    });

    setMemoryCards(shuffleArray(newMemoryCards));
    return true;
  }, []);

  const prepareOrderVerseItems = useCallback((difficulty: OrderVerseDifficultySetting, category?: TriviaCategory): boolean => {
    let sourceForOrderVerse = TRIVIA_SOURCE_DATA;
    if (category && category !== TriviaCategory.ALL) {
        sourceForOrderVerse = TRIVIA_SOURCE_DATA.filter(item => item.category === category);
    }

    const numVerses = difficulty.versesToOrder === -1 ? sourceForOrderVerse.length : difficulty.versesToOrder;
    if (sourceForOrderVerse.length < numVerses && difficulty.versesToOrder !== -1) return false;
    if (sourceForOrderVerse.length === 0) return false;

    const selectedItems = shuffleArray([...sourceForOrderVerse]).slice(0, numVerses);
    const newOrderVerseItems: OrderVerseItem[] = selectedItems.map(item => {
        const correctWords = tokenizeVerse(item.text);
        return {
            id: item.id,
            reference: item.correctAnswer,
            category: item.category,
            correctOrderText: item.text,
            words: shuffleArray([...correctWords]), 
            correctWordOrder: correctWords, 
        };
    });
    setOrderVerseItems(newOrderVerseItems);
    return true;
  }, []);

  const prepareReciteVerseItems = useCallback((difficulty: ReciteVerseDifficultySetting, category?: TriviaCategory): boolean => {
    let sourceData = TRIVIA_SOURCE_DATA;
    if (category && category !== TriviaCategory.ALL) sourceData = TRIVIA_SOURCE_DATA.filter(item => item.category === category);

    const numVerses = difficulty.versesToRecite === -1 ? sourceData.length : difficulty.versesToRecite;
    if (sourceData.length < numVerses && difficulty.versesToRecite !== -1) return false;

    const selectedItems = shuffleArray([...sourceData]).slice(0, numVerses);
    const newReciteItems: ReciteVerseItem[] = selectedItems.map(item => ({
        id: item.id,
        reference: item.correctAnswer,
        category: item.category,
        fullText: item.text,
        words: tokenizeVerse(item.text),
    }));
    setReciteVerseItems(newReciteItems);
    return true;
  }, []);

  const prepareTimelineItems = useCallback((difficulty: TimelineDifficultySetting): boolean => {
    const sourceData = TIMELINE_SOURCE_DATA;
    const numItems = difficulty.itemsToOrder === -1 ? sourceData.length : difficulty.itemsToOrder;
    if (sourceData.length < MINIMUM_ITEMS_TIMELINE) return false;

    const selectedItems = shuffleArray([...sourceData]).slice(0, Math.min(numItems, sourceData.length));
    setTimelineItems(selectedItems);
    return true;
  }, []);

  const prepareBookSortItems = useCallback((difficulty: BookSortDifficultySetting): boolean => {
    let sourceData = BIBLE_BOOKS_DATA;
    // Filter by Testament
    if (difficulty.testament === 'OLD') {
        sourceData = sourceData.filter(b => b.testament === 'Old');
    } else if (difficulty.testament === 'NEW') {
        sourceData = sourceData.filter(b => b.testament === 'New');
    }

    if (sourceData.length < MINIMUM_BOOKS_SORT) {
        alert("No hay suficientes libros configurados para este modo.");
        return false;
    }

    const numBooks = difficulty.booksToOrder === -1 ? sourceData.length : difficulty.booksToOrder;
    // Always shuffle first then take slice to get random books
    const selectedItems = shuffleArray([...sourceData]).slice(0, Math.min(numBooks, sourceData.length));
    setBookSortItems(selectedItems);
    return true;
  }, []);

  const handleStartGame = useCallback((
    gameMode: GameMode,
    settings: any,
    category?: TriviaCategory
  ) => {
    setIsLoading(true);
    setSelectedGameMode(gameMode);
    setActiveGameSettings(settings);
    setActiveCategory(category); 
    setGameResults(null); 

    // Clear previous states
    setTriviaQuestions([]);
    setMemoryCards([]);
    setOrderVerseItems([]);
    setReciteVerseItems([]);
    setTimelineItems([]);
    setBookSortItems([]);

    let ready = false;
    if (gameMode === GameMode.TRIVIA) ready = prepareTriviaQuestions(category!, settings);
    else if (gameMode === GameMode.MEMORY) ready = prepareMemoryCards(settings, category);
    else if (gameMode === GameMode.ORDER_VERSE) ready = prepareOrderVerseItems(settings, category);
    else if (gameMode === GameMode.RECITE_VERSE) ready = prepareReciteVerseItems(settings, category);
    else if (gameMode === GameMode.TIMELINE) ready = prepareTimelineItems(settings);
    else if (gameMode === GameMode.BOOK_SORT) ready = prepareBookSortItems(settings);

    if (ready) {
      navigateTo(GameScreenState.Playing);
    } else {
      setIsLoading(false);
    }
  }, [prepareTriviaQuestions, prepareMemoryCards, prepareOrderVerseItems, prepareReciteVerseItems, prepareTimelineItems, prepareBookSortItems, navigateTo]);

  const handleGameEnd = useCallback((results: GameEndPayload) => {
    setGameResults(results);
    navigateTo(GameScreenState.Results);
  }, [navigateTo]);

  const handlePlayAgain = useCallback(() => {
    if (!activeGameSettings || !selectedGameMode) { navigateTo(GameScreenState.Home); return; }
    // Re-trigger start logic with same settings
    handleStartGame(selectedGameMode, activeGameSettings, activeCategory);
  }, [selectedGameMode, activeGameSettings, activeCategory, handleStartGame, navigateTo]);

  const handleChangeSettings = useCallback(() => {
    navigateTo(GameScreenState.Home);
  }, [navigateTo]);

  const renderScreen = () => {
    if (isLoading && (currentScreen === GameScreenState.Home || currentScreen === GameScreenState.Playing)) { 
        return <div className="text-center p-8 text-xl font-semibold text-gray-700">Preparando juego...</div>;
    }
    const isTrainingMode = activeGameSettings?.level === Difficulty.EASY;

    switch (currentScreen) {
      case GameScreenState.Home:
        return (
          <HomeScreen onStartGame={handleStartGame} disabled={isLoading} />
        );
      case GameScreenState.Playing:
        if (selectedGameMode === GameMode.TRIVIA) {
          if (triviaQuestions.length === 0) return null;
          return <GameScreen questions={triviaQuestions} onGameEnd={handleGameEnd} timerDuration={(activeGameSettings as DifficultySetting).timerDuration} isTraining={isTrainingMode} />;
        } 
        if (selectedGameMode === GameMode.MEMORY) {
            if (memoryCards.length === 0) return null;
            return <MemoryGameScreen cards={memoryCards} difficulty={activeGameSettings as MemoryDifficultySetting} onGameEnd={handleGameEnd} isTraining={isTrainingMode} />;
        }
        if (selectedGameMode === GameMode.ORDER_VERSE) {
            if (orderVerseItems.length === 0) return null;
            return <OrderVerseScreen items={orderVerseItems} difficulty={activeGameSettings as OrderVerseDifficultySetting} onGameEnd={handleGameEnd} isTraining={isTrainingMode} />;
        }
        if (selectedGameMode === GameMode.RECITE_VERSE) {
            if (reciteVerseItems.length === 0) return null;
            return <ReciteVerseScreen items={reciteVerseItems} difficultySettings={activeGameSettings as ReciteVerseDifficultySetting} onGameEnd={handleGameEnd} isTraining={isTrainingMode} />;
        }
        if (selectedGameMode === GameMode.TIMELINE) {
             if (timelineItems.length === 0) return null;
             return <TimelineGameScreen items={timelineItems} difficulty={activeGameSettings as TimelineDifficultySetting} onGameEnd={handleGameEnd} isTraining={isTrainingMode} />;
        }
        if (selectedGameMode === GameMode.BOOK_SORT) {
             if (bookSortItems.length === 0) return null;
             return <BookSortGameScreen books={bookSortItems} difficulty={activeGameSettings as BookSortDifficultySetting} onGameEnd={handleGameEnd} isTraining={isTrainingMode} />;
        }
        return null;

      case GameScreenState.Results:
        if (!gameResults) return null;
        return (
          <FinalScreen results={gameResults} onPlayAgain={handlePlayAgain} onChangeSettings={handleChangeSettings} />
        );
      default: 
        navigateTo(GameScreenState.Home);
        return null;
    }
  };

  if (!appReady) return <IntroAnimationScreen logoSrc={LOGO_URL} />;

  return (
    <div className={`min-h-screen bg-gradient-celestial text-gray-800 flex flex-col font-sans ${appReady ? 'anim-fade-in' : 'opacity-0'}`}>
      <header className="w-full bg-white/80 backdrop-blur-md shadow-md py-2 px-4 sticky top-0 z-30">
        <div className="max-w-6xl mx-auto flex items-center">
          <button onClick={() => navigateTo(GameScreenState.Home)} className="p-0 bg-transparent border-none cursor-pointer focus:outline-none focus:ring-2 focus:ring-amber-500 rounded-md">
            <img src={LOGO_URL} alt="Logo" className="h-10 w-auto" /> 
          </button>
        </div>
      </header>
      <main className="flex-grow flex flex-col items-center justify-center p-2 sm:p-4">
        <div className={`w-full max-w-2xl ${viewAnimation}`}>
          {renderScreen()}
        </div>
      </main>
      <footer className="w-full bg-gray-100/60 backdrop-blur-sm text-gray-600 text-xs text-center p-3 mt-auto">
        <div className="max-w-6xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-2">
          <div className="flex items-center gap-2">
            <img src={LOGO_URL} alt="Logo" className="h-6 w-auto opacity-75" />
            <span>© {new Date().getFullYear()} Iglesia Defensores de la Fe Cristiana.</span>
          </div>
          <div className="flex space-x-4 text-lg">
             <i className="fab fa-facebook-f text-gray-400"></i>
             <i className="fab fa-instagram text-gray-400"></i>
             <i className="fab fa-youtube text-gray-400"></i>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { GameMode, TriviaCategory, Difficulty, DifficultySetting, MemoryDifficultySetting, OrderVerseDifficultySetting, ReciteVerseDifficultySetting, TimelineDifficultySetting, BookSortDifficultySetting } from '../types';
import { CATEGORIES, DIFFICULTY_LEVELS, MEMORY_DIFFICULTY_SETTINGS, ORDER_VERSE_DIFFICULTY_SETTINGS, RECITE_VERSE_DIFFICULTY_SETTINGS, TIMELINE_DIFFICULTY_SETTINGS, BOOK_SORT_DIFFICULTY_SETTINGS } from '../constants';
import Button from './Button';
import Dropdown from './Dropdown';

interface HomeScreenProps {
  onStartGame: (
    gameMode: GameMode,
    settings: any,
    category?: TriviaCategory
  ) => void;
  disabled?: boolean;
}

const HomeScreen: React.FC<HomeScreenProps> = ({ 
  onStartGame, 
  disabled = false
}) => {
  const [selectedGameMode, setSelectedGameMode] = useState<GameMode>(GameMode.TRIVIA);
  const [selectedCategory, setSelectedCategory] = useState<TriviaCategory>(CATEGORIES[0]);

  const [currentTriviaDifficulty, setCurrentTriviaDifficulty] = useState<DifficultySetting>(DIFFICULTY_LEVELS[1]);
  const [currentMemoryDifficulty, setCurrentMemoryDifficulty] = useState<MemoryDifficultySetting>(MEMORY_DIFFICULTY_SETTINGS[1]);
  const [currentOrderVerseDifficulty, setCurrentOrderVerseDifficulty] = useState<OrderVerseDifficultySetting>(ORDER_VERSE_DIFFICULTY_SETTINGS[1]);
  const [currentReciteVerseDifficulty, setCurrentReciteVerseDifficulty] = useState<ReciteVerseDifficultySetting>(RECITE_VERSE_DIFFICULTY_SETTINGS[1]);
  const [currentTimelineDifficulty, setCurrentTimelineDifficulty] = useState<TimelineDifficultySetting>(TIMELINE_DIFFICULTY_SETTINGS[1]);
  const [currentBookSortDifficulty, setCurrentBookSortDifficulty] = useState<BookSortDifficultySetting>(BOOK_SORT_DIFFICULTY_SETTINGS[1]);


  const categoryOptions = CATEGORIES.map(cat => ({ value: cat, label: cat }));

  const triviaDifficultyOptions = DIFFICULTY_LEVELS.map(diff => ({ value: diff.level, label: diff.label }));
  const memoryDifficultyOptions = MEMORY_DIFFICULTY_SETTINGS.map(diff => ({ value: diff.level, label: diff.label }));
  const orderVerseDifficultyOptions = ORDER_VERSE_DIFFICULTY_SETTINGS.map(diff => ({ value: diff.level, label: diff.label }));
  const reciteVerseDifficultyOptions = RECITE_VERSE_DIFFICULTY_SETTINGS.map(diff => ({ value: diff.level, label: diff.label }));
  const timelineDifficultyOptions = TIMELINE_DIFFICULTY_SETTINGS.map(diff => ({ value: diff.level, label: diff.label }));
  const bookSortDifficultyOptions = BOOK_SORT_DIFFICULTY_SETTINGS.map(diff => ({ value: diff.level, label: diff.label }));

  // Handlers
  const handleTriviaDifficultyChange = (value: Difficulty) => setCurrentTriviaDifficulty(DIFFICULTY_LEVELS.find(d => d.level === value) || DIFFICULTY_LEVELS[0]);
  const handleMemoryDifficultyChange = (value: Difficulty) => setCurrentMemoryDifficulty(MEMORY_DIFFICULTY_SETTINGS.find(d => d.level === value) || MEMORY_DIFFICULTY_SETTINGS[0]);
  const handleOrderVerseDifficultyChange = (value: Difficulty) => setCurrentOrderVerseDifficulty(ORDER_VERSE_DIFFICULTY_SETTINGS.find(d => d.level === value) || ORDER_VERSE_DIFFICULTY_SETTINGS[0]);
  const handleReciteVerseDifficultyChange = (value: Difficulty) => setCurrentReciteVerseDifficulty(RECITE_VERSE_DIFFICULTY_SETTINGS.find(d => d.level === value) || RECITE_VERSE_DIFFICULTY_SETTINGS[0]);
  const handleTimelineDifficultyChange = (value: Difficulty) => setCurrentTimelineDifficulty(TIMELINE_DIFFICULTY_SETTINGS.find(d => d.level === value) || TIMELINE_DIFFICULTY_SETTINGS[0]);
  const handleBookSortDifficultyChange = (value: Difficulty) => setCurrentBookSortDifficulty(BOOK_SORT_DIFFICULTY_SETTINGS.find(d => d.level === value) || BOOK_SORT_DIFFICULTY_SETTINGS[0]);

  const handleStartClick = () => {
    switch(selectedGameMode) {
        case GameMode.TRIVIA: onStartGame(GameMode.TRIVIA, currentTriviaDifficulty, selectedCategory); break;
        case GameMode.MEMORY: onStartGame(GameMode.MEMORY, currentMemoryDifficulty, selectedCategory); break;
        case GameMode.ORDER_VERSE: onStartGame(GameMode.ORDER_VERSE, currentOrderVerseDifficulty, selectedCategory); break;
        case GameMode.RECITE_VERSE: onStartGame(GameMode.RECITE_VERSE, currentReciteVerseDifficulty, selectedCategory); break;
        case GameMode.TIMELINE: onStartGame(GameMode.TIMELINE, currentTimelineDifficulty); break;
        case GameMode.BOOK_SORT: onStartGame(GameMode.BOOK_SORT, currentBookSortDifficulty); break;
    }
  };

  const startButtonText = () => {
    if (disabled) return "Preparando...";
    return "Comenzar Juego";
  };

  const gameModeButtons = [
    { mode: GameMode.TRIVIA, label: "Trivia" },
    { mode: GameMode.MEMORY, label: "Memoria" },
    { mode: GameMode.ORDER_VERSE, label: "Orden Verso" },
    { mode: GameMode.RECITE_VERSE, label: "Recitar" },
    { mode: GameMode.TIMELINE, label: "Línea Tiempo" },
    { mode: GameMode.BOOK_SORT, label: "Orden Libros" }
  ];

  const showCategory = selectedGameMode === GameMode.TRIVIA || selectedGameMode === GameMode.MEMORY || selectedGameMode === GameMode.ORDER_VERSE || selectedGameMode === GameMode.RECITE_VERSE;

  return (
    <div className="flex flex-col items-center justify-center text-center p-4 sm:p-6 min-h-[520px] bg-white/30 backdrop-blur-md rounded-xl shadow-xl">
      <h1 className="font-serif text-4xl md:text-5xl font-bold text-gray-700 mb-3 anim-fade-in-up">
        Desafío Bíblico
      </h1>
      <p className="text-lg text-gray-600 mb-6 sm:mb-8 anim-fade-in-up animation-delay-100">
        Elige tu juego y pon a prueba tu conocimiento.
      </p>

      <div className="w-full max-w-xs mb-6 space-y-5">
        <div className="anim-fade-in-up animation-delay-200">
          <label htmlFor="gamemode-select" className="block text-sm font-medium text-gray-600 mb-2 text-left">
            Modo de juego:
          </label>
          <div className="grid grid-cols-2 gap-2">
            {gameModeButtons.map(({mode, label}) => (
              <Button
                key={mode}
                onClick={() => setSelectedGameMode(mode)}
                variant={selectedGameMode === mode ? 'primary' : 'secondary'}
                className={`w-full py-2.5 !rounded-lg text-xs sm:text-sm transition-colors duration-200 ${selectedGameMode === mode ? 'shadow-md' : 'hover:bg-amber-100/70'}`}
                disabled={disabled}
                aria-pressed={selectedGameMode === mode}
              >
                {label}
              </Button>
            ))}
          </div>
        </div>

        {showCategory && (
            <div className="anim-fade-in-up animation-delay-300">
              <label htmlFor="category-select" className="block text-sm font-medium text-gray-600 mb-2 text-left">
                Categoría:
              </label>
              <Dropdown
                id="category-select"
                options={categoryOptions}
                selectedValue={selectedCategory}
                onChange={setSelectedCategory}
                ariaLabel="Seleccionar categoría"
                disabled={disabled}
              />
            </div>
        )}

        <div className="anim-fade-in-up animation-delay-400">
          <label htmlFor="difficulty-select" className="block text-sm font-medium text-gray-600 mb-2 text-left">
            Dificultad:
          </label>
          {selectedGameMode === GameMode.TRIVIA && (
            <Dropdown options={triviaDifficultyOptions} selectedValue={currentTriviaDifficulty.level} onChange={handleTriviaDifficultyChange} disabled={disabled} />
          )}
          {selectedGameMode === GameMode.MEMORY && (
            <Dropdown options={memoryDifficultyOptions} selectedValue={currentMemoryDifficulty.level} onChange={handleMemoryDifficultyChange} disabled={disabled} />
          )}
          {selectedGameMode === GameMode.ORDER_VERSE && (
            <Dropdown options={orderVerseDifficultyOptions} selectedValue={currentOrderVerseDifficulty.level} onChange={handleOrderVerseDifficultyChange} disabled={disabled} />
          )}
          {selectedGameMode === GameMode.RECITE_VERSE && (
            <Dropdown options={reciteVerseDifficultyOptions} selectedValue={currentReciteVerseDifficulty.level} onChange={handleReciteVerseDifficultyChange} disabled={disabled} />
          )}
          {selectedGameMode === GameMode.TIMELINE && (
            <Dropdown options={timelineDifficultyOptions} selectedValue={currentTimelineDifficulty.level} onChange={handleTimelineDifficultyChange} disabled={disabled} />
          )}
          {selectedGameMode === GameMode.BOOK_SORT && (
            <Dropdown options={bookSortDifficultyOptions} selectedValue={currentBookSortDifficulty.level} onChange={handleBookSortDifficultyChange} disabled={disabled} />
          )}
        </div>
      </div>

      <Button 
        onClick={handleStartClick}
        variant="primary"
        className="w-full max-w-xs text-lg mt-4 sm:mt-6 anim-fade-in-up animation-delay-500"
        aria-label={`Comenzar ${selectedGameMode}`}
        disabled={disabled}
      >
        {startButtonText()}
      </Button>
    </div>
  );
};

export default HomeScreen;

import React from 'react';
import Button from './Button';
import { GameEndPayload, GameMode } from '../types';

interface FinalScreenProps {
  results: GameEndPayload;
  onPlayAgain: () => void; 
  onChangeSettings: () => void;
}

const FinalScreen: React.FC<FinalScreenProps> = ({ results, onPlayAgain, onChangeSettings }) => {
  let titleMessage = "¡Sigue adelante!";
  let scoreDisplay: React.ReactNode;

  if (results.type === 'trivia') {
    const percentageCorrect = results.totalQuestions > 0 ? Math.round((results.correctAnswersCount / results.totalQuestions) * 100) : 0;
    if (percentageCorrect >= 80) titleMessage = "¡Excelente trabajo en la Trivia! Tu conocimiento es una luz.";
    else if (percentageCorrect >= 50) titleMessage = "¡Buen esfuerzo en la Trivia! Sigue explorando la Palabra.";
    else titleMessage = "¡Ánimo en la Trivia! Cada día es una oportunidad para aprender.";

    scoreDisplay = (
      <>
        <div>
          <p className="text-xl text-gray-600">Puntuación Neta Final (Trivia):</p>
          <p className="text-5xl md:text-6xl font-bold text-amber-600">{results.netScore}</p>
        </div>
        <div>
            <p className="text-lg text-gray-500">Respuestas Correctas:</p>
            <p className="text-3xl font-semibold text-green-600">{results.correctAnswersCount} / {results.totalQuestions}</p>
            <p className="text-xl text-gray-500 mt-1">({percentageCorrect}% de aciertos)</p>
        </div>
      </>
    );
  } else if (results.type === 'memory') {
    if (results.moves <= results.totalPairs * 2.5) titleMessage = "¡Memoria prodigiosa! ¡Excelente!";
    else if (results.moves <= results.totalPairs * 3.5) titleMessage = "¡Muy bien jugado el juego de memoria!";
    else titleMessage = "¡Buen intento en el juego de memoria! ¡Sigue practicando!";

    scoreDisplay = (
      <>
        <div>
          <p className="text-xl text-gray-600">Juego de Memoria Completado:</p>
           <p className="text-3xl font-semibold text-green-600">{results.totalPairs} Pares Encontrados</p>
        </div>
        <div>
          <p className="text-lg text-gray-500">Movimientos Realizados:</p>
          <p className="text-5xl md:text-6xl font-bold text-amber-600">{results.moves}</p>
        </div>
      </>
    );
  } else if (results.type === 'order_verse') {
    const percentageCorrect = results.versesAttempted > 0 ? Math.round((results.versesCorrect / results.versesAttempted) * 100) : 0;
    if (percentageCorrect >= 80) titleMessage = "¡Maestro del Orden! Versículos armados a la perfección.";
    else if (percentageCorrect >= 50) titleMessage = "¡Bien hecho ordenando los versículos!";
    else titleMessage = "¡Sigue practicando el orden de los versículos!";

    scoreDisplay = (
        <>
            <div>
                <p className="text-xl text-gray-600">Juego "Ordenar Versículo" Completado:</p>
                <p className="text-5xl md:text-6xl font-bold text-amber-600">{results.score} Puntos</p>
            </div>
            <div>
                <p className="text-lg text-gray-500">Versículos Correctos:</p>
                <p className="text-3xl font-semibold text-green-600">{results.versesCorrect} / {results.versesAttempted}</p>
                <p className="text-xl text-gray-500 mt-1">({percentageCorrect}% de aciertos)</p>
            </div>
        </>
    );
  } else if (results.type === 'recite_verse') {
    const percentageCorrect = results.versesAttempted > 0 ? Math.round((results.versesCorrect / results.versesAttempted) * 100) : 0;
    if (percentageCorrect === 100) titleMessage = "¡Recitación Impecable! Eres un experto en la Palabra.";
    else if (percentageCorrect >= 70) titleMessage = "¡Muy buena recitación! Sigue memorizando.";
    else if (percentageCorrect >= 40) titleMessage = "¡Buen esfuerzo recitando!";
    else titleMessage = "¡Sigue practicando la recitación!";

    scoreDisplay = (
      <>
        <div>
          <p className="text-xl text-gray-600">Juego "Recitar Versículo" Completado:</p>
          <p className="text-5xl md:text-6xl font-bold text-amber-600">{results.score} Puntos</p>
        </div>
        <div>
          <p className="text-lg text-gray-500">Versículos Correctos:</p>
          <p className="text-3xl font-semibold text-green-600">{results.versesCorrect} / {results.versesAttempted}</p>
          <p className="text-xl text-gray-500 mt-1">({percentageCorrect}% de aciertos)</p>
        </div>
      </>
    );
  } else if (results.type === 'timeline') {
    if (results.score === results.totalItems && results.mistakes === 0) titleMessage = "¡Cronología Perfecta! Conoces la historia de Jesús.";
    else if (results.score === results.totalItems) titleMessage = "¡Muy bien! Has completado la línea del tiempo.";
    else titleMessage = "¡Buen intento! Repasa la armonía de los evangelios.";

    scoreDisplay = (
      <>
        <div>
          <p className="text-xl text-gray-600">Eventos Ordenados:</p>
          <p className="text-5xl md:text-6xl font-bold text-green-600">{results.score} / {results.totalItems}</p>
        </div>
        <div>
          <p className="text-lg text-gray-500">Errores cometidos:</p>
          <p className="text-3xl font-semibold text-red-500">{results.mistakes}</p>
        </div>
      </>
    );
  } else if (results.type === 'book_sort') {
    if (results.score === results.totalBooks && results.mistakes === 0) titleMessage = "¡Bibliotecario Divino! Orden perfecto.";
    else if (results.score === results.totalBooks) titleMessage = "¡Libros ordenados correctamente! Buen trabajo.";
    else titleMessage = "¡Sigue aprendiendo el orden de los libros!";

    scoreDisplay = (
      <>
        <div>
            <p className="text-xl text-gray-600">Libros Ordenados:</p>
            <p className="text-5xl md:text-6xl font-bold text-green-600">{results.score} / {results.totalBooks}</p>
        </div>
        <div>
            <p className="text-lg text-gray-500">Errores cometidos:</p>
            <p className="text-3xl font-semibold text-red-500">{results.mistakes}</p>
        </div>
      </>
    );
  }


  return (
    <div className="flex flex-col items-center justify-center text-center p-6 sm:p-8 min-h-[400px] bg-white/30 backdrop-blur-md rounded-xl shadow-xl">
      <h2 className="font-serif text-3xl md:text-4xl font-bold text-gray-700 mb-4 anim-fade-in-up">{titleMessage}</h2>
      <div className="my-6 space-y-4 anim-fade-in-up animation-delay-100">{scoreDisplay}</div>
      <div className="flex flex-col sm:flex-row gap-4 w-full max-w-xs sm:max-w-md mt-4">
        <Button onClick={onPlayAgain} variant="primary" className="w-full text-lg anim-fade-in-up animation-delay-200">Jugar de Nuevo</Button>
        <Button onClick={onChangeSettings} variant="secondary" className="w-full text-lg anim-fade-in-up animation-delay-300">Cambiar Configuración</Button>
      </div>
    </div>
  );
};

export default FinalScreen;

import React, { useState, useEffect, useCallback } from 'react';
import { TimelineItemData, TimelineDifficultySetting, GameEndPayload, TimelineGameEndPayload } from '../types';
import Button from './Button';
import ProgressBar from './ProgressBar';

interface TimelineGameScreenProps {
  items: TimelineItemData[];
  difficulty: TimelineDifficultySetting;
  onGameEnd: (results: GameEndPayload) => void;
  isTraining?: boolean;
}

interface PlacedItem {
  slotIndex: number; // 0-based index of the slot
  item: TimelineItemData | null;
  status: 'empty' | 'placed' | 'correct' | 'incorrect';
}

const TimelineGameScreen: React.FC<TimelineGameScreenProps> = ({ items, difficulty, onGameEnd, isTraining = false }) => {
  // Correctly sorted items for internal validation (subset of full list)
  const [sortedCorrectItems, setSortedCorrectItems] = useState<TimelineItemData[]>([]);
  // Shuffled items available to be placed
  const [availableItems, setAvailableItems] = useState<TimelineItemData[]>([]);
  // The timeline slots
  const [slots, setSlots] = useState<PlacedItem[]>([]);

  const [score, setScore] = useState(0);
  const [mistakes, setMistakes] = useState(0);

  // Interaction state
  const [selectedItemId, setSelectedItemId] = useState<string | null>(null); // For click-to-place
  const [isVerified, setIsVerified] = useState(false);

  const [timeLeft, setTimeLeft] = useState(difficulty.timerDuration || 0);
  const [timerId, setTimerId] = useState<number | null>(null);

  useEffect(() => {
    // 1. Sort input items chronologically to establish the "Truth"
    const sorted = [...items].sort((a, b) => a.orderId - b.orderId);
    setSortedCorrectItems(sorted);

    // 2. Shuffle them for the "Bank"
    const shuffled = [...items];
    for (let i = shuffled.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    setAvailableItems(shuffled);

    // 3. Create Empty Slots
    const initialSlots: PlacedItem[] = Array(items.length).fill(null).map((_, i) => ({
      slotIndex: i,
      item: null,
      status: 'empty'
    }));
    setSlots(initialSlots);

    // Reset stats
    setScore(0);
    setMistakes(0);
    setIsVerified(false);
    setSelectedItemId(null);

    // Timer Logic
    if (timerId) clearInterval(timerId);
    if (!isTraining && difficulty.timerDuration && difficulty.timerDuration > 0) {
        setTimeLeft(difficulty.timerDuration);
        const tid = setInterval(() => {
            setTimeLeft(prev => {
                if (prev <= 1) {
                    clearInterval(tid as unknown as number);
                    finishGame(score, mistakes + 1); // Timeout counts as mistake/end
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);
        setTimerId(tid as unknown as number);
    }

    return () => {
        if (timerId) clearInterval(timerId);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items, difficulty, isTraining]);


  const finishGame = (finalScore: number, finalMistakes: number) => {
    if (timerId) clearInterval(timerId);
    const results: TimelineGameEndPayload = {
      type: 'timeline',
      score: finalScore,
      totalItems: items.length,
      mistakes: finalMistakes
    };
    onGameEnd(results);
  };

  const handleFinishTraining = () => {
      finishGame(score, mistakes);
  };

  // --- Interaction Logic ---

  const handleItemSelect = (item: TimelineItemData) => {
    if (isVerified) return;
    if (selectedItemId === item.id) {
        setSelectedItemId(null); // Deselect
    } else {
        setSelectedItemId(item.id);
    }
  };

  const handleSlotClick = (slotIndex: number) => {
    if (isVerified) return;

    // If we have an item selected from the bank, place it here
    if (selectedItemId) {
        const itemToPlace = availableItems.find(i => i.id === selectedItemId);
        if (itemToPlace) {
            placeItemInSlot(itemToPlace, slotIndex);
            setSelectedItemId(null);
        }
        return;
    }

    // If slot has an item, return it to bank (deselect/remove)
    const slot = slots[slotIndex];
    if (slot.item) {
        removeItemFromSlot(slotIndex);
    }
  };

  const placeItemInSlot = (item: TimelineItemData, slotIndex: number) => {
    // 1. Remove item from Available
    setAvailableItems(prev => prev.filter(i => i.id !== item.id));

    // 2. Check if slot already has an item, if so, swap (return old to bank)
    const currentSlotItem = slots[slotIndex].item;
    if (currentSlotItem) {
        setAvailableItems(prev => [...prev, currentSlotItem]);
    }

    // 3. Update Slot
    setSlots(prev => prev.map((s, i) => 
        i === slotIndex ? { ...s, item: item, status: 'placed' } : s
    ));
  };

  const removeItemFromSlot = (slotIndex: number) => {
    const slotItem = slots[slotIndex].item;
    if (!slotItem) return;

    // Return to bank
    setAvailableItems(prev => [...prev, slotItem]);
    // Clear slot
    setSlots(prev => prev.map((s, i) => 
        i === slotIndex ? { ...s, item: null, status: 'empty' } : s
    ));
  };

  // --- HTML5 Drag & Drop Wrappers ---

  const handleDragStart = (e: React.DragEvent, item: TimelineItemData) => {
    if (isVerified) return;
    e.dataTransfer.setData("text/plain", item.id);
    e.dataTransfer.effectAllowed = "move";
  };

  const handleDragOver = (e: React.DragEvent) => {
    if (isVerified) return;
    e.preventDefault(); // Necessary to allow dropping
    e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e: React.DragEvent, slotIndex: number) => {
    if (isVerified) return;
    e.preventDefault();
    const itemId = e.dataTransfer.getData("text/plain");

    // Find item (could be in bank OR another slot)
    let item = availableItems.find(i => i.id === itemId);

    // If not in bank, check slots (moving from one slot to another)
    if (!item) {
        const sourceSlot = slots.find(s => s.item?.id === itemId);
        if (sourceSlot && sourceSlot.item) {
            item = sourceSlot.item;
            // Clear source slot
             setSlots(prev => prev.map((s) => 
                s.slotIndex === sourceSlot.slotIndex ? { ...s, item: null, status: 'empty' } : s
            ));
        }
    }

    if (item) {
        placeItemInSlot(item, slotIndex);
    }
  };

  // --- Verification ---

  const checkOrder = () => {
    let currentScore = 0;
    let currentMistakes = mistakes;
    let allCorrect = true;

    const newSlots = slots.map((slot, index) => {
        if (!slot.item) return slot;

        // The correct item for this slot (index) should match the sortedCorrectItems[index]
        const correctItemForThisSlot = sortedCorrectItems[index];
        const isCorrect = slot.item.id === correctItemForThisSlot.id;

        if (isCorrect) {
            currentScore++;
            return { ...slot, status: 'correct' as const };
        } else {
            currentMistakes++;
            allCorrect = false;
            return { ...slot, status: 'incorrect' as const };
        }
    });

    setSlots(newSlots);
    setScore(currentScore);
    setMistakes(currentMistakes);

    if (allCorrect && availableItems.length === 0) {
        setIsVerified(true); // Game Over (Success)
        // Delay slightly to show visual success state
        setTimeout(() => {
            finishGame(currentScore, currentMistakes);
        }, 1500);
    } else {
        // Not done yet or mistakes made. 
        // Logic: Keep correct ones fixed? 
        // For simplicity: Just show status. 
        // If "Incorrect", allow user to move them again?
        // The prompt says: "Incorrect -> bounce". 
        // We will reset status of incorrect items to 'placed' after a delay so they can be moved again.

        setTimeout(() => {
            setSlots(prev => prev.map(s => {
                if (s.status === 'incorrect') {
                    // return item to available? Or just reset status?
                    // "Rebota" implies it stays there but looks wrong, or pops back. 
                    // Let's pop it back to the bank to force re-think.
                    if (s.item) setAvailableItems(p => [...p, s.item!]);
                    return { ...s, item: null, status: 'empty' }; 
                }
                return s;
            }));
        }, 800);
    }
  };

  const allSlotsFilled = slots.every(s => s.item !== null);

  return (
    <div className="flex flex-col min-h-[600px] relative pt-20 pb-4 bg-white/30 backdrop-blur-md rounded-xl shadow-xl w-full">
      {/* Header */}
      <div className="fixed top-0 left-1/2 transform -translate-x-1/2 w-full max-w-4xl px-4 py-2 bg-white/80 backdrop-blur-sm shadow-md z-20 rounded-b-xl">
        <div className="max-w-4xl mx-auto flex justify-between items-center text-sm text-gray-700">
           <div className="flex items-center gap-2">
               <span className="font-bold text-amber-600">Línea del Tiempo</span>
               {isTraining && (
                    <button onClick={handleFinishTraining} className="text-xs bg-red-100 text-red-600 px-2 py-1 rounded hover:bg-red-200 font-bold">
                        Terminar
                    </button>
                )}
           </div>

           {!isTraining && difficulty.timerDuration && difficulty.timerDuration > 0 && (
             <span className={`font-mono font-bold ${timeLeft < 15 ? 'text-red-500 anim-pulse' : 'text-gray-600'}`}>
                ⏱ {timeLeft}s
             </span>
           )}
        </div>
        {!isTraining && <ProgressBar current={slots.filter(s => s.status === 'correct').length} total={items.length} />}
      </div>

      <div className="flex-grow flex flex-col p-2 sm:p-4 overflow-hidden">

        {/* Timeline Area (Slots) - Horizontal Scrollable */}
        <div className="w-full overflow-x-auto pb-4 mb-4">
             <div className="flex space-x-2 sm:space-x-4 min-w-max px-2">
                 {slots.map((slot, index) => (
                     <div 
                        key={`slot-${index}`}
                        onClick={() => handleSlotClick(index)}
                        onDragOver={handleDragOver}
                        onDrop={(e) => handleDrop(e, index)}
                        className={`
                            relative w-32 h-40 sm:w-40 sm:h-52 border-2 border-dashed rounded-lg flex flex-col items-center justify-center p-2 transition-all duration-300
                            ${slot.status === 'correct' ? 'border-green-500 bg-green-50' : ''}
                            ${slot.status === 'incorrect' ? 'border-red-500 bg-red-50 anim-shake' : ''}
                            ${slot.status === 'placed' ? 'border-amber-400 bg-white' : 'border-gray-300 bg-gray-50/50'}
                            ${selectedItemId && !slot.item ? 'ring-2 ring-amber-300 ring-opacity-50' : ''}
                        `}
                     >
                        {/* Timeline Connector Line */}
                        <div className="absolute top-1/2 -left-4 w-4 h-1 bg-gray-300 -z-10 hidden sm:block"></div>
                        {index < slots.length - 1 && <div className="absolute top-1/2 -right-4 w-4 h-1 bg-gray-300 -z-10 hidden sm:block"></div>}

                        <div className="absolute top-[-10px] bg-gray-200 text-gray-600 text-xs font-bold px-2 py-0.5 rounded-full z-10">
                            #{index + 1}
                        </div>

                        {slot.item ? (
                            <div className="text-center w-full h-full flex flex-col justify-between pointer-events-none">
                                <p className="text-xs sm:text-sm font-semibold text-gray-800 line-clamp-4">{slot.item.event}</p>
                                <span className="text-[10px] text-amber-600 font-mono mt-1">{slot.item.reference}</span>
                            </div>
                        ) : (
                            <span className="text-gray-300 font-bold text-2xl">+</span>
                        )}
                     </div>
                 ))}
             </div>
        </div>

        {/* Bank Area */}
        <div className="flex-grow bg-white/40 rounded-lg p-3 sm:p-4 overflow-y-auto">
             <p className="text-center text-sm text-gray-600 mb-2 italic">
                {selectedItemId 
                    ? "Toca un hueco numerado arriba para colocar la tarjeta." 
                    : "Arrastra eventos a la línea de tiempo o toca para seleccionar."}
             </p>
             <div className="flex flex-wrap justify-center gap-2 sm:gap-3">
                 {availableItems.map((item) => (
                     <div
                        key={item.id}
                        draggable={!isVerified}
                        onDragStart={(e) => handleDragStart(e, item)}
                        onClick={() => handleItemSelect(item)}
                        className={`
                            w-28 sm:w-32 h-24 sm:h-28 bg-white border shadow-sm rounded-lg p-2 flex flex-col justify-center items-center text-center cursor-pointer hover:shadow-md active:scale-95 transition-transform
                            ${selectedItemId === item.id ? 'ring-2 ring-amber-500 scale-105 border-amber-500' : 'border-gray-200'}
                        `}
                     >
                         <p className="text-xs font-medium text-gray-800 line-clamp-3">{item.event}</p>
                     </div>
                 ))}
                 {availableItems.length === 0 && !isVerified && (
                     <p className="text-gray-500 italic mt-4">Todos los eventos colocados. ¡Verifica!</p>
                 )}
             </div>
        </div>
      </div>

      {/* Footer Action */}
      <div className="p-4 bg-white/60 backdrop-blur-md rounded-b-xl">
         <Button 
            onClick={checkOrder}
            variant="primary"
            className="w-full"
            disabled={!allSlotsFilled || isVerified}
         >
            {isVerified ? "¡Completado!" : "Verificar Orden"}
         </Button>
      </div>
    </div>
  );
};

