import React, { useState, useCallback, useEffect } from 'react';
import { 
  GameScreenState, GameMode, TriviaCategory, TriviaQuestion, DifficultySetting, 
  MemoryDifficultySetting, SourceDataItem, TriviaOption, GameEndPayload, MemoryCardData,
  OrderVerseItem, OrderVerseDifficultySetting, ReciteVerseItem, ReciteVerseDifficultySetting, Difficulty,
  TimelineItemData, TimelineDifficultySetting, BookData, BookSortDifficultySetting 
} from './types';
import { 
  TRIVIA_SOURCE_DATA, TIMELINE_SOURCE_DATA, BIBLE_BOOKS_DATA, CATEGORIES, DIFFICULTY_LEVELS, MEMORY_DIFFICULTY_SETTINGS, 
  ORDER_VERSE_DIFFICULTY_SETTINGS, RECITE_VERSE_DIFFICULTY_SETTINGS, TIMELINE_DIFFICULTY_SETTINGS, BOOK_SORT_DIFFICULTY_SETTINGS,
  MINIMUM_SOURCE_DATA_ITEMS_TRIVIA, MINIMUM_PAIRS_MEMORY, MINIMUM_VERSES_ORDER_VERSE, MINIMUM_VERSES_RECITE_VERSE, MINIMUM_ITEMS_TIMELINE, MINIMUM_BOOKS_SORT
} from './constants';
import HomeScreen from './components/HomeScreen';
import GameScreen from './components/GameScreen'; 
import MemoryGameScreen from './components/MemoryGameScreen';
import OrderVerseScreen from './components/OrderVerseScreen'; 
import ReciteVerseScreen from './components/ReciteVerseScreen';
import TimelineGameScreen from './components/TimelineGameScreen';
import BookSortGameScreen from './components/BookSortGameScreen';
import FinalScreen from './components/FinalScreen';

const shuffleArray = <T,>(array: T[]): T[] => {
  const newArray = [...array];
  for (let i = newArray.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [newArray[i], newArray[j]] = [newArray[j], newArray[i]];
  }
  return newArray;
};

const tokenizeVerse = (text: string): string[] => {
  return text.split(/\s+/).filter(word => word.length > 0).map(word => word.trim());
};

const LOGO_URL = "https://i.postimg.cc/9MZ6CRqt/Logo.png";

const IntroAnimationScreen: React.FC<{ logoSrc: string }> = ({ logoSrc }) => {
  return (
    <div className="fixed top-0 left-0 w-full h-full flex flex-col items-center justify-center bg-gradient-celestial z-50 anim-fade-in">
      <img src={logoSrc} alt="Logo Defensores de la Fe" className="w-48 h-auto md:w-64 intro-logo-animate" />
      <p className="text-xl font-serif text-gray-700 mt-6 animate-pulse">Cargando Desafío Bíblico...</p>
    </div>
  );
};

const App: React.FC = () => {
  const [currentScreen, setCurrentScreen] = useState<GameScreenState>(GameScreenState.Home);
  const [selectedGameMode, setSelectedGameMode] = useState<GameMode>(GameMode.TRIVIA);
  const [activeGameSettings, setActiveGameSettings] = useState<DifficultySetting | MemoryDifficultySetting | OrderVerseDifficultySetting | ReciteVerseDifficultySetting | TimelineDifficultySetting | BookSortDifficultySetting | null>(null);
  const [activeCategory, setActiveCategory] = useState<TriviaCategory | undefined>(CATEGORIES[0]);

  const [gameResults, setGameResults] = useState<GameEndPayload | null>(null);

  const [triviaQuestions, setTriviaQuestions] = useState<TriviaQuestion[]>([]);
  const [memoryCards, setMemoryCards] = useState<MemoryCardData[]>([]);
  const [orderVerseItems, setOrderVerseItems] = useState<OrderVerseItem[]>([]);
  const [reciteVerseItems, setReciteVerseItems] = useState<ReciteVerseItem[]>([]);
  const [timelineItems, setTimelineItems] = useState<TimelineItemData[]>([]);
  const [bookSortItems, setBookSortItems] = useState<BookData[]>([]);

  const [viewAnimation, setViewAnimation] = useState('anim-fade-in');
  const [isLoading, setIsLoading] = useState(false);
  const [appReady, setAppReady] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      setAppReady(true);
    }, 2800); 
    return () => clearTimeout(timer);
  }, []);

  const navigateTo = useCallback((newScreen: GameScreenState) => {
    setViewAnimation('anim-fade-out');
    setTimeout(() => {
      setCurrentScreen(newScreen);
      setViewAnimation('anim-fade-in');
      setIsLoading(false); 
    }, 300); 
  }, []);

  const prepareTriviaQuestions = useCallback((category: TriviaCategory, difficulty: DifficultySetting): boolean => {
    if (TRIVIA_SOURCE_DATA.length < MINIMUM_SOURCE_DATA_ITEMS_TRIVIA) {
        alert(`No hay suficientes datos base (${TRIVIA_SOURCE_DATA.length}) para Trivia.`);
        return false;
    }
    let candidateBaseItems: SourceDataItem[] = category === TriviaCategory.ALL ? 
        [...TRIVIA_SOURCE_DATA] : 
        TRIVIA_SOURCE_DATA.filter(item => item.category === category);

    const numQuestionsToSelect = difficulty.questions === -1 ? candidateBaseItems.length : difficulty.questions;

    if (candidateBaseItems.length === 0) {
      alert(`No hay preguntas de trivia disponibles para la categoría "${category}".`);
      return false;
    }
    const actualNumQuestions = Math.min(candidateBaseItems.length, numQuestionsToSelect);
    const selectedBaseItems = shuffleArray(candidateBaseItems).slice(0, actualNumQuestions);

    const newGameQuestions: TriviaQuestion[] = selectedBaseItems.map((baseItem) => {
      const correctOption: TriviaOption = { text: baseItem.correctAnswer, isCorrect: true };
      let incorrectAnswersPool = TRIVIA_SOURCE_DATA
        .filter(item => item.id !== baseItem.id) 
        .map(item => item.correctAnswer);

      incorrectAnswersPool = Array.from(new Set(incorrectAnswersPool.filter(ans => ans !== baseItem.correctAnswer)));
      const numberOfIncorrectOptionsToPick = Math.min(3, incorrectAnswersPool.length); 
      const incorrectOptionsTexts = shuffleArray(incorrectAnswersPool).slice(0, numberOfIncorrectOptionsToPick);
      const incorrectOptions: TriviaOption[] = incorrectOptionsTexts.map(text => ({ text, isCorrect: false }));
      const allOptions = shuffleArray([correctOption, ...incorrectOptions]);

      return {
        id: baseItem.id,
        verse: baseItem.text,
        options: allOptions,
        category: baseItem.category,
      };
    });

    const validGameQuestions = newGameQuestions.filter(q => q.options.length >= 2);
    if (validGameQuestions.length === 0) return false;
    setTriviaQuestions(validGameQuestions);
    return true;
  }, []);

  const prepareMemoryCards = useCallback((difficulty: MemoryDifficultySetting, category?: TriviaCategory): boolean => {
    const numPairs = difficulty.pairs;
    let sourceForMemory = TRIVIA_SOURCE_DATA;

    if (category && category !== TriviaCategory.ALL) {
      sourceForMemory = TRIVIA_SOURCE_DATA.filter(item => item.category === category);
    }
    if (sourceForMemory.length < numPairs) {
        alert("No hay suficientes datos para memoria.");
        return false;
    }
    const selectedItems = shuffleArray([...sourceForMemory]).slice(0, numPairs);

    let newMemoryCards: MemoryCardData[] = [];
    selectedItems.forEach((item) => {
      newMemoryCards.push({ id: `${item.id}_text`, pairId: item.id, content: item.text, isFlipped: false, isMatched: false });
      newMemoryCards.push({ id: `${item.id}_ref`, pairId: item.id, content: item.correctAnswer, isFlipped: false, isMatched: false });
    });

    setMemoryCards(shuffleArray(newMemoryCards));
    return true;
  }, []);

  const prepareOrderVerseItems = useCallback((difficulty: OrderVerseDifficultySetting, category?: TriviaCategory): boolean => {
    let sourceForOrderVerse = TRIVIA_SOURCE_DATA;
    if (category && category !== TriviaCategory.ALL) {
        sourceForOrderVerse = TRIVIA_SOURCE_DATA.filter(item => item.category === category);
    }

    const numVerses = difficulty.versesToOrder === -1 ? sourceForOrderVerse.length : difficulty.versesToOrder;
    if (sourceForOrderVerse.length < numVerses && difficulty.versesToOrder !== -1) return false;
    if (sourceForOrderVerse.length === 0) return false;

    const selectedItems = shuffleArray([...sourceForOrderVerse]).slice(0, numVerses);
    const newOrderVerseItems: OrderVerseItem[] = selectedItems.map(item => {
        const correctWords = tokenizeVerse(item.text);
        return {
            id: item.id,
            reference: item.correctAnswer,
            category: item.category,
            correctOrderText: item.text,
            words: shuffleArray([...correctWords]), 
            correctWordOrder: correctWords, 
        };
    });
    setOrderVerseItems(newOrderVerseItems);
    return true;
  }, []);

  const prepareReciteVerseItems = useCallback((difficulty: ReciteVerseDifficultySetting, category?: TriviaCategory): boolean => {
    let sourceData = TRIVIA_SOURCE_DATA;
    if (category && category !== TriviaCategory.ALL) sourceData = TRIVIA_SOURCE_DATA.filter(item => item.category === category);

    const numVerses = difficulty.versesToRecite === -1 ? sourceData.length : difficulty.versesToRecite;
    if (sourceData.length < numVerses && difficulty.versesToRecite !== -1) return false;

    const selectedItems = shuffleArray([...sourceData]).slice(0, numVerses);
    const newReciteItems: ReciteVerseItem[] = selectedItems.map(item => ({
        id: item.id,
        reference: item.correctAnswer,
        category: item.category,
        fullText: item.text,
        words: tokenizeVerse(item.text),
    }));
    setReciteVerseItems(newReciteItems);
    return true;
  }, []);

  const prepareTimelineItems = useCallback((difficulty: TimelineDifficultySetting): boolean => {
    const sourceData = TIMELINE_SOURCE_DATA;
    const numItems = difficulty.itemsToOrder === -1 ? sourceData.length : difficulty.itemsToOrder;
    if (sourceData.length < MINIMUM_ITEMS_TIMELINE) return false;

    const selectedItems = shuffleArray([...sourceData]).slice(0, Math.min(numItems, sourceData.length));
    setTimelineItems(selectedItems);
    return true;
  }, []);

  const prepareBookSortItems = useCallback((difficulty: BookSortDifficultySetting): boolean => {
    let sourceData = BIBLE_BOOKS_DATA;
    // Filter by Testament
    if (difficulty.testament === 'OLD') {
        sourceData = sourceData.filter(b => b.testament === 'Old');
    } else if (difficulty.testament === 'NEW') {
        sourceData = sourceData.filter(b => b.testament === 'New');
    }

    if (sourceData.length < MINIMUM_BOOKS_SORT) {
        alert("No hay suficientes libros configurados para este modo.");
        return false;
    }

    const numBooks = difficulty.booksToOrder === -1 ? sourceData.length : difficulty.booksToOrder;
    // Always shuffle first then take slice to get random books
    const selectedItems = shuffleArray([...sourceData]).slice(0, Math.min(numBooks, sourceData.length));
    setBookSortItems(selectedItems);
    return true;
  }, []);

  const handleStartGame = useCallback((
    gameMode: GameMode,
    settings: any,
    category?: TriviaCategory
  ) => {
    setIsLoading(true);
    setSelectedGameMode(gameMode);
    setActiveGameSettings(settings);
    setActiveCategory(category); 
    setGameResults(null); 

    // Clear previous states
    setTriviaQuestions([]);
    setMemoryCards([]);
    setOrderVerseItems([]);
    setReciteVerseItems([]);
    setTimelineItems([]);
    setBookSortItems([]);

    let ready = false;
    if (gameMode === GameMode.TRIVIA) ready = prepareTriviaQuestions(category!, settings);
    else if (gameMode === GameMode.MEMORY) ready = prepareMemoryCards(settings, category);
    else if (gameMode === GameMode.ORDER_VERSE) ready = prepareOrderVerseItems(settings, category);
    else if (gameMode === GameMode.RECITE_VERSE) ready = prepareReciteVerseItems(settings, category);
    else if (gameMode === GameMode.TIMELINE) ready = prepareTimelineItems(settings);
    else if (gameMode === GameMode.BOOK_SORT) ready = prepareBookSortItems(settings);

    if (ready) {
      navigateTo(GameScreenState.Playing);
    } else {
      setIsLoading(false);
    }
  }, [prepareTriviaQuestions, prepareMemoryCards, prepareOrderVerseItems, prepareReciteVerseItems, prepareTimelineItems, prepareBookSortItems, navigateTo]);

  const handleGameEnd = useCallback((results: GameEndPayload) => {
    setGameResults(results);
    navigateTo(GameScreenState.Results);
  }, [navigateTo]);

  const handlePlayAgain = useCallback(() => {
    if (!activeGameSettings || !selectedGameMode) { navigateTo(GameScreenState.Home); return; }
    // Re-trigger start logic with same settings
    handleStartGame(selectedGameMode, activeGameSettings, activeCategory);
  }, [selectedGameMode, activeGameSettings, activeCategory, handleStartGame, navigateTo]);

  const handleChangeSettings = useCallback(() => {
    navigateTo(GameScreenState.Home);
  }, [navigateTo]);

  const renderScreen = () => {
    if (isLoading && (currentScreen === GameScreenState.Home || currentScreen === GameScreenState.Playing)) { 
        return <div className="text-center p-8 text-xl font-semibold text-gray-700">Preparando juego...</div>;
    }
    const isTrainingMode = activeGameSettings?.level === Difficulty.EASY;

    switch (currentScreen) {
      case GameScreenState.Home:
        return (
          <HomeScreen onStartGame={handleStartGame} disabled={isLoading} />
        );
      case GameScreenState.Playing:
        if (selectedGameMode === GameMode.TRIVIA) {
          if (triviaQuestions.length === 0) return null;
          return <GameScreen questions={triviaQuestions} onGameEnd={handleGameEnd} timerDuration={(activeGameSettings as DifficultySetting).timerDuration} isTraining={isTrainingMode} />;
        } 
        if (selectedGameMode === GameMode.MEMORY) {
            if (memoryCards.length === 0) return null;
            return <MemoryGameScreen cards={memoryCards} difficulty={activeGameSettings as MemoryDifficultySetting} onGameEnd={handleGameEnd} isTraining={isTrainingMode} />;
        }
        if (selectedGameMode === GameMode.ORDER_VERSE) {
            if (orderVerseItems.length === 0) return null;
            return <OrderVerseScreen items={orderVerseItems} difficulty={activeGameSettings as OrderVerseDifficultySetting} onGameEnd={handleGameEnd} isTraining={isTrainingMode} />;
        }
        if (selectedGameMode === GameMode.RECITE_VERSE) {
            if (reciteVerseItems.length === 0) return null;
            return <ReciteVerseScreen items={reciteVerseItems} difficultySettings={activeGameSettings as ReciteVerseDifficultySetting} onGameEnd={handleGameEnd} isTraining={isTrainingMode} />;
        }
        if (selectedGameMode === GameMode.TIMELINE) {
             if (timelineItems.length === 0) return null;
             return <TimelineGameScreen items={timelineItems} difficulty={activeGameSettings as TimelineDifficultySetting} onGameEnd={handleGameEnd} isTraining={isTrainingMode} />;
        }
        if (selectedGameMode === GameMode.BOOK_SORT) {
             if (bookSortItems.length === 0) return null;
             return <BookSortGameScreen books={bookSortItems} difficulty={activeGameSettings as BookSortDifficultySetting} onGameEnd={handleGameEnd} isTraining={isTrainingMode} />;
        }
        return null;

      case GameScreenState.Results:
        if (!gameResults) return null;
        return (
          <FinalScreen results={gameResults} onPlayAgain={handlePlayAgain} onChangeSettings={handleChangeSettings} />
        );
      default: 
        navigateTo(GameScreenState.Home);
        return null;
    }
  };

  if (!appReady) return <IntroAnimationScreen logoSrc={LOGO_URL} />;

  return (
    <div className={`min-h-screen bg-gradient-celestial text-gray-800 flex flex-col font-sans ${appReady ? 'anim-fade-in' : 'opacity-0'}`}>
      <header className="w-full bg-white/80 backdrop-blur-md shadow-md py-2 px-4 sticky top-0 z-30">
        <div className="max-w-6xl mx-auto flex items-center">
          <button onClick={() => navigateTo(GameScreenState.Home)} className="p-0 bg-transparent border-none cursor-pointer focus:outline-none focus:ring-2 focus:ring-amber-500 rounded-md">
            <img src={LOGO_URL} alt="Logo" className="h-10 w-auto" /> 
          </button>
        </div>
      </header>
      <main className="flex-grow flex flex-col items-center justify-center p-2 sm:p-4">
        <div className={`w-full max-w-2xl ${viewAnimation}`}>
          {renderScreen()}
        </div>
      </main>
      <footer className="w-full bg-gray-100/60 backdrop-blur-sm text-gray-600 text-xs text-center p-3 mt-auto">
        <div className="max-w-6xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-2">
          <div className="flex items-center gap-2">
            <img src={LOGO_URL} alt="Logo" className="h-6 w-auto opacity-75" />
            <span>© {new Date().getFullYear()} Iglesia Defensores de la Fe Cristiana.</span>
          </div>
          <div className="flex space-x-4 text-lg">
             <i className="fab fa-facebook-f text-gray-400"></i>
             <i className="fab fa-instagram text-gray-400"></i>
             <i className="fab fa-youtube text-gray-400"></i>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { BookData, BookSortDifficultySetting, GameEndPayload, BookSortGameEndPayload } from '../types';
import Button from './Button';
import ProgressBar from './ProgressBar';

interface BookSortGameScreenProps {
  books: BookData[];
  difficulty: BookSortDifficultySetting;
  onGameEnd: (results: GameEndPayload) => void;
  isTraining?: boolean;
}

interface PlacedBook {
  slotIndex: number;
  book: BookData | null;
  status: 'empty' | 'placed' | 'correct' | 'incorrect';
}

const InfoIcon: React.FC<{ className?: string }> = ({ className = "w-4 h-4" }) => (
  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className={className}>
    <path strokeLinecap="round" strokeLinejoin="round" d="m11.25 11.25.041-.02a.75.75 0 0 1 1.063.852l-.708 2.836a.75.75 0 0 0 1.063.853l.041-.021M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-9-3.75h.008v.008H12V8.25Z" />
  </svg>
);

const BookSortGameScreen: React.FC<BookSortGameScreenProps> = ({ books, difficulty, onGameEnd, isTraining = false }) => {
  const [sortedCorrectBooks, setSortedCorrectBooks] = useState<BookData[]>([]);
  const [availableBooks, setAvailableBooks] = useState<BookData[]>([]);
  const [slots, setSlots] = useState<PlacedBook[]>([]);
  const [selectedBookId, setSelectedBookId] = useState<string | null>(null);

  const [score, setScore] = useState(0);
  const [mistakes, setMistakes] = useState(0);
  const [isVerified, setIsVerified] = useState(false);
  const [infoModalBook, setInfoModalBook] = useState<BookData | null>(null);

  const [timeLeft, setTimeLeft] = useState(difficulty.timerDuration || 0);
  const [timerId, setTimerId] = useState<number | null>(null);

  useEffect(() => {
    // 1. Determine Correct Order based on Criteria
    let sorted = [...books];
    if (difficulty.criteria === 'ALPHABETICAL') {
        sorted.sort((a, b) => a.name.localeCompare(b.name));
    } else if (difficulty.criteria === 'CHRONOLOGICAL') {
        sorted.sort((a, b) => a.chronologicalOrder - b.chronologicalOrder);
    } else { // CANONICAL
        sorted.sort((a, b) => a.canonicalOrder - b.canonicalOrder);
    }
    setSortedCorrectBooks(sorted);

    // 2. Shuffle for bank
    const shuffled = [...books];
    for (let i = shuffled.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    setAvailableBooks(shuffled);

    // 3. Init Slots
    setSlots(Array(books.length).fill(null).map((_, i) => ({
      slotIndex: i,
      book: null,
      status: 'empty'
    })));

    setScore(0);
    setMistakes(0);
    setIsVerified(false);
    setSelectedBookId(null);

    // Timer logic
    if (timerId) clearInterval(timerId);
    if (!isTraining && difficulty.timerDuration && difficulty.timerDuration > 0) {
        setTimeLeft(difficulty.timerDuration);
        const tid = setInterval(() => {
            setTimeLeft(prev => {
                if (prev <= 1) {
                    clearInterval(tid as unknown as number);
                    finishGame(score, mistakes + 1);
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);
        setTimerId(tid as unknown as number);
    }

    return () => { if (timerId) clearInterval(timerId); };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [books, difficulty, isTraining]);

  const finishGame = (finalScore: number, finalMistakes: number) => {
    if (timerId) clearInterval(timerId);
    const results: BookSortGameEndPayload = {
      type: 'book_sort',
      score: finalScore,
      totalBooks: books.length,
      mistakes: finalMistakes
    };
    onGameEnd(results);
  };

  const handleFinishTraining = () => finishGame(score, mistakes);

  // --- Logic Helpers ---
  const handleBookSelect = (book: BookData) => {
    if (isVerified) return;
    if (selectedBookId === book.id) setSelectedBookId(null);
    else setSelectedBookId(book.id);
  };

  const handleSlotClick = (slotIndex: number) => {
    if (isVerified) return;
    if (selectedBookId) {
        const bookToPlace = availableBooks.find(b => b.id === selectedBookId);
        if (bookToPlace) {
            placeBookInSlot(bookToPlace, slotIndex);
            setSelectedBookId(null);
        }
        return;
    }
    // Return to bank
    const slot = slots[slotIndex];
    if (slot.book) {
        setAvailableBooks(prev => [...prev, slot.book!]);
        setSlots(prev => prev.map((s, i) => i === slotIndex ? { ...s, book: null, status: 'empty' } : s));
    }
  };

  const placeBookInSlot = (book: BookData, slotIndex: number) => {
    setAvailableBooks(prev => prev.filter(b => b.id !== book.id));
    const currentSlotBook = slots[slotIndex].book;
    if (currentSlotBook) setAvailableBooks(prev => [...prev, currentSlotBook]);

    setSlots(prev => prev.map((s, i) => i === slotIndex ? { ...s, book: book, status: 'placed' } : s));
  };

  const checkOrder = () => {
    let currentScore = 0;
    let currentMistakes = mistakes;
    let allCorrect = true;

    const newSlots = slots.map((slot, index) => {
        if (!slot.book) return slot;
        const correctBook = sortedCorrectBooks[index];
        const isCorrect = slot.book.id === correctBook.id;

        if (isCorrect) currentScore++;
        else {
            currentMistakes++;
            allCorrect = false;
        }
        return { ...slot, status: isCorrect ? 'correct' : 'incorrect' } as PlacedBook;
    });

    setSlots(newSlots);
    setScore(currentScore);
    setMistakes(currentMistakes);

    if (allCorrect && availableBooks.length === 0) {
        setIsVerified(true);
        setTimeout(() => finishGame(currentScore, currentMistakes), 1500);
    } else {
        setTimeout(() => {
            setSlots(prev => prev.map(s => {
                if (s.status === 'incorrect') {
                    if (s.book) setAvailableBooks(p => [...p, s.book!]);
                    return { ...s, book: null, status: 'empty' }; 
                }
                return s;
            }));
        }, 800);
    }
  };

  // --- Drag & Drop ---
  const handleDragStart = (e: React.DragEvent, book: BookData) => {
    if (isVerified) return;
    e.dataTransfer.setData("text/plain", book.id);
    e.dataTransfer.effectAllowed = "move";
  };

  const handleDragOver = (e: React.DragEvent) => {
    if (isVerified) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e: React.DragEvent, slotIndex: number) => {
    if (isVerified) return;
    e.preventDefault();
    const bookId = e.dataTransfer.getData("text/plain");
    let book = availableBooks.find(b => b.id === bookId);

    if (!book) { // Move from another slot
        const sourceSlot = slots.find(s => s.book?.id === bookId);
        if (sourceSlot && sourceSlot.book) {
            book = sourceSlot.book;
            setSlots(prev => prev.map(s => s.slotIndex === sourceSlot.slotIndex ? { ...s, book: null, status: 'empty' } : s));
        }
    }
    if (book) placeBookInSlot(book, slotIndex);
  };

  const handleInfoClick = (e: React.MouseEvent, book: BookData) => {
      e.stopPropagation();
      setInfoModalBook(book);
  };

  const criteriaLabel = difficulty.criteria === 'ALPHABETICAL' ? 'A-Z' : difficulty.criteria === 'CHRONOLOGICAL' ? 'Crono' : 'Biblia';

  return (
    <div className="flex flex-col min-h-[600px] relative pt-20 pb-4 bg-white/30 backdrop-blur-md rounded-xl shadow-xl w-full">
      {/* Header */}
      <div className="fixed top-0 left-1/2 transform -translate-x-1/2 w-full max-w-4xl px-4 py-2 bg-white/80 backdrop-blur-sm shadow-md z-20 rounded-b-xl">
        <div className="max-w-4xl mx-auto flex justify-between items-center text-sm text-gray-700">
           <div className="flex items-center gap-2">
               <span className="font-bold text-amber-600">Orden {criteriaLabel}</span>
               {isTraining && <button onClick={handleFinishTraining} className="text-xs bg-red-100 text-red-600 px-2 py-1 rounded font-bold">Terminar</button>}
           </div>
           {!isTraining && difficulty.timerDuration && difficulty.timerDuration > 0 && (
             <span className={`font-mono font-bold ${timeLeft < 15 ? 'text-red-500 anim-pulse' : 'text-gray-600'}`}>⏱ {timeLeft}s</span>
           )}
        </div>
        {!isTraining && <ProgressBar current={slots.filter(s => s.status === 'correct').length} total={books.length} />}
      </div>

      <div className="flex-grow flex flex-col p-2 sm:p-4 gap-4 overflow-hidden">

        {/* Horizontal Shelf (Slots) */}
        <div className="w-full overflow-x-auto pb-6 pt-2">
            <div className="flex space-x-3 px-2 min-w-max items-end h-48 sm:h-56">
                {slots.map((slot, index) => (
                    <div
                        key={`slot-${slot.slotIndex}`}
                        onClick={() => handleSlotClick(slot.slotIndex)}
                        onDragOver={handleDragOver}
                        onDrop={(e) => handleDrop(e, slot.slotIndex)}
                        className={`
                            relative w-28 h-40 sm:w-32 sm:h-48 border-b-8 rounded-t-md flex items-end justify-center transition-all duration-300
                            ${slot.status === 'empty' ? 'border-gray-300 bg-gray-50/30' : ''}
                            ${slot.status === 'placed' ? 'border-amber-700' : ''}
                            ${slot.status === 'correct' ? 'border-green-600' : ''}
                            ${slot.status === 'incorrect' ? 'border-red-500 anim-shake' : ''}
                            ${selectedBookId && !slot.book ? 'bg-amber-100/50' : ''}
                        `}
                    >   
                         {/* Slot Number Label */}
                         <div className="absolute -bottom-8 left-1/2 transform -translate-x-1/2 text-gray-500 font-mono text-xs font-bold">
                            #{index + 1}
                         </div>

                         {/* Empty Slot Placeholder */}
                         {!slot.book && (
                             <div className="w-full h-full border-2 border-dashed border-gray-300 rounded-t-md flex items-center justify-center">
                                 <span className="text-gray-300 text-2xl font-bold">+</span>
                             </div>
                         )}

                         {/* Placed Book */}
                         {slot.book && (
                             <div 
                                className={`
                                    w-full h-[95%] rounded-r-md rounded-l-sm shadow-md flex flex-col items-center justify-between p-2 cursor-pointer relative group mx-1 mb-0.5
                                    ${slot.status === 'correct' ? 'bg-green-600 text-white' : ''}
                                    ${slot.status === 'incorrect' ? 'bg-red-500 text-white' : ''}
                                    ${slot.status === 'placed' ? 'bg-amber-800 text-amber-50' : ''}
                                `}
                                onDoubleClick={() => setInfoModalBook(slot.book)}
                                style={{
                                    boxShadow: 'inset 4px 0 5px rgba(0,0,0,0.2), 2px 2px 5px rgba(0,0,0,0.3)'
                                }}
                             >
                                <div className="w-full text-center border-b border-white/20 pb-1">
                                    <span className="text-xs sm:text-sm font-serif font-bold leading-tight block break-words">{slot.book.name}</span>
                                </div>
                                <div className="flex-grow flex items-center justify-center">
                                    <span className="text-[10px] opacity-70 writing-vertical-rl transform rotate-180 uppercase tracking-widest">{slot.book.author}</span>
                                </div>
                                <button 
                                    onClick={(e) => handleInfoClick(e, slot.book!)}
                                    className="absolute top-1 right-1 text-white/50 hover:text-white"
                                >
                                    <InfoIcon />
                                </button>
                             </div>
                         )}
                    </div>
                ))}
                {/* Extra spacer at end */}
                <div className="w-4 flex-shrink-0"></div>
            </div>
            {/* Shelf Wood Plank visual */}
            <div className="h-4 w-full min-w-max bg-amber-800 rounded-sm shadow-lg mt-[-2px] mx-2"></div>
        </div>

        {/* Book Bank (Bottom) */}
        <div className="flex-grow bg-white/40 rounded-t-xl border-t border-white/50 p-3 sm:p-4 overflow-y-auto shadow-inner">
            <p className="text-center text-sm text-gray-600 mb-2 italic">
                {selectedBookId 
                    ? "Toca un hueco vacío en el estante de arriba." 
                    : "Arrastra los libros al estante superior en el orden correcto."}
            </p>
            <div className="flex flex-wrap justify-center gap-3 pb-20">
                {availableBooks.map(book => (
                    <div
                        key={book.id}
                        draggable={!isVerified}
                        onDragStart={(e) => handleDragStart(e, book)}
                        onClick={() => handleBookSelect(book)}
                        onDoubleClick={() => setInfoModalBook(book)}
                        className={`
                            w-20 h-28 sm:w-24 sm:h-32 bg-amber-700 text-amber-50 rounded-r-md rounded-l-sm shadow-md flex flex-col items-center justify-between p-2 cursor-grab active:cursor-grabbing hover:bg-amber-600 transition-transform
                            ${selectedBookId === book.id ? 'ring-4 ring-amber-300 scale-105 z-10' : ''}
                        `}
                        style={{
                            boxShadow: 'inset 3px 0 4px rgba(0,0,0,0.2), 1px 1px 3px rgba(0,0,0,0.2)'
                        }}
                    >
                        <span className="text-xs font-serif font-bold text-center leading-tight line-clamp-2">{book.name}</span>
                        <div className="w-full h-px bg-white/20 my-1"></div>
                        <button onClick={(e) => handleInfoClick(e, book)} className="text-amber-200 hover:text-white mb-1"><InfoIcon /></button>
                    </div>
                ))}
                {availableBooks.length === 0 && !isVerified && (
                     <p className="text-gray-500 italic mt-8">Todos los libros están en el estante.</p>
                )}
            </div>
        </div>
      </div>

      {/* Footer Action */}
      <div className="fixed bottom-0 w-full max-w-2xl p-4 bg-white/90 backdrop-blur-md border-t border-gray-200 z-20 self-center rounded-t-xl">
         <Button onClick={checkOrder} variant="primary" className="w-full shadow-lg" disabled={slots.some(s => s.book === null) || isVerified}>
            {isVerified ? "¡Completado!" : "Verificar Orden"}
         </Button>
      </div>

      {/* Info Modal */}
      {infoModalBook && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 anim-fade-in" onClick={() => setInfoModalBook(null)}>
            <div className="bg-white rounded-xl shadow-2xl p-6 max-w-sm w-full relative" onClick={e => e.stopPropagation()}>
                <h3 className="text-2xl font-serif text-amber-700 font-bold mb-1">{infoModalBook.name}</h3>
                <p className="text-sm text-gray-500 mb-4">{infoModalBook.testament === 'Old' ? 'Antiguo Testamento' : 'Nuevo Testamento'} • Autor: {infoModalBook.author}</p>
                <div className="bg-amber-50 p-3 rounded-lg border border-amber-100 mb-4">
                    <p className="text-gray-700 text-sm leading-relaxed">{infoModalBook.summary}</p>
                </div>
                <div className="grid grid-cols-2 gap-2 text-xs text-gray-600">
                    <div className="bg-gray-100 p-2 rounded">Orden Bíblico: #{infoModalBook.canonicalOrder}</div>
                    <div className="bg-gray-100 p-2 rounded">Orden Crono (aprox): #{infoModalBook.chronologicalOrder}</div>
                </div>
                <Button onClick={() => setInfoModalBook(null)} variant="secondary" className="w-full mt-4 py-2">Cerrar</Button>
            </div>
        </div>
      )}
    </div>
  );
};

export default BookSortGameScreen;

export enum GameScreenState {
  Home,
  Playing,
  Results,
}

export enum GameMode {
  TRIVIA = "Trivia Bíblica",
  MEMORY = "Juego de Memoria",
  ORDER_VERSE = "Ordenar Versículo",
  RECITE_VERSE = "Recitar Versículo",
  TIMELINE = "Línea del Tiempo",
  BOOK_SORT = "Orden de Libros", 
}

export enum TriviaCategory {
  PROMISES = "Promesas",
  COMMANDMENTS = "Mandamientos",
  JESUS_SAID = "Jesús (dijo)", 
  ALL = "Todas las categorías",
}

export interface SourceDataItem {
  id: string;
  text: string;
  correctAnswer: string; 
  category: TriviaCategory;
}

export interface TriviaOption {
  text: string;
  isCorrect: boolean;
}

export interface TriviaQuestion {
  id: string;
  verse: string;
  options: TriviaOption[];
  category: TriviaCategory;
}

export interface SelectedAnswerInfo {
  isCorrectResponse: boolean;
  selectedIndex: number;
  correctIndex: number;
  isTimeout: boolean;
}

export enum Difficulty {
  EASY = "Fácil",
  MEDIUM = "Medio",
  DIFFICULT = "Difícil",
}

export interface DifficultySetting { 
  level: Difficulty;
  questions: number;
  label: string;
  timerDuration: number; 
}

export interface MemoryDifficultySetting { 
  level: Difficulty;
  pairs: number;
  grid: { rows: number; cols: number };
  label: string;
  timerPerItem?: number; 
}

export interface OrderVerseItem {
  id: string; 
  reference: string; 
  category: TriviaCategory;
  correctOrderText: string; 
  words: string[]; 
  correctWordOrder: string[]; 
}

export interface OrderVerseDifficultySetting { 
  level: Difficulty;
  versesToOrder: number;
  label: string;
  timerPerItem?: number; 
}

export interface ReciteVerseItem {
  id: string; 
  reference: string; 
  category: TriviaCategory;
  fullText: string; 
  words: string[]; 
}

export type VisibleLettersMode = 'firstAndLast' | 'firstOnly' | 'none';

export interface ReciteVerseDifficultySetting {
  level: Difficulty;
  versesToRecite: number;
  visibleLettersMode: VisibleLettersMode;
  label: string;
  timerPerItem?: number; 
}

// --- TIMELINE TYPES ---
export interface TimelineItemData {
  id: string;
  event: string;
  reference: string;
