import React, { useState, useEffect } from 'react';
import { BookData, BookSortDifficultySetting, GameEndPayload, BookSortGameEndPayload } from '../types';
import Button from './Button';
import ProgressBar from './ProgressBar';

interface BookSortGameScreenProps {
  books: BookData[];
  difficulty: BookSortDifficultySetting;
  onGameEnd: (results: GameEndPayload) => void;
  isTraining?: boolean;
}

interface PlacedBook {
  slotIndex: number;
  book: BookData | null;
  status: 'empty' | 'placed' | 'correct' | 'incorrect';
}

const InfoIcon: React.FC<{ className?: string }> = ({ className = "w-3 h-3" }) => (
  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className={className}>
    <path strokeLinecap="round" strokeLinejoin="round" d="m11.25 11.25.041-.02a.75.75 0 0 1 1.063.852l-.708 2.836a.75.75 0 0 0 1.063.853l.041-.021M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-9-3.75h.008v.008H12V8.25Z" />
  </svg>
);

const BookSortGameScreen: React.FC<BookSortGameScreenProps> = ({ books, difficulty, onGameEnd, isTraining = false }) => {
  const [sortedCorrectBooks, setSortedCorrectBooks] = useState<BookData[]>([]);
  const [availableBooks, setAvailableBooks] = useState<BookData[]>([]);
  const [slots, setSlots] = useState<PlacedBook[]>([]);
  const [selectedBookId, setSelectedBookId] = useState<string | null>(null);

  const [score, setScore] = useState(0);
  const [mistakes, setMistakes] = useState(0);
  const [isVerified, setIsVerified] = useState(false);
  const [infoModalBook, setInfoModalBook] = useState<BookData | null>(null);

  const [timeLeft, setTimeLeft] = useState(difficulty.timerDuration || 0);
  const [timerId, setTimerId] = useState<number | null>(null);

  useEffect(() => {
    // 1. Determine Correct Order based on Criteria
    let sorted = [...books];
    if (difficulty.criteria === 'ALPHABETICAL') {
        sorted.sort((a, b) => a.name.localeCompare(b.name));
    } else if (difficulty.criteria === 'CHRONOLOGICAL') {
        sorted.sort((a, b) => a.chronologicalOrder - b.chronologicalOrder);
    } else { // CANONICAL
        sorted.sort((a, b) => a.canonicalOrder - b.canonicalOrder);
    }
    setSortedCorrectBooks(sorted);

    // 2. Shuffle for bank
    const shuffled = [...books];
    for (let i = shuffled.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    setAvailableBooks(shuffled);

    // 3. Init Slots
    setSlots(Array(books.length).fill(null).map((_, i) => ({
      slotIndex: i,
      book: null,
      status: 'empty'
    })));

    setScore(0);
    setMistakes(0);
    setIsVerified(false);
    setSelectedBookId(null);

    // Timer logic
    if (timerId) clearInterval(timerId);
    if (!isTraining && difficulty.timerDuration && difficulty.timerDuration > 0) {
        setTimeLeft(difficulty.timerDuration);
        const tid = setInterval(() => {
            setTimeLeft(prev => {
                if (prev <= 1) {
                    clearInterval(tid as unknown as number);
                    finishGame(score, mistakes + 1);
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);
        setTimerId(tid as unknown as number);
    }

    return () => { if (timerId) clearInterval(timerId); };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [books, difficulty, isTraining]);

  const finishGame = (finalScore: number, finalMistakes: number) => {
    if (timerId) clearInterval(timerId);
    const results: BookSortGameEndPayload = {
      type: 'book_sort',
      score: finalScore,
      totalBooks: books.length,
      mistakes: finalMistakes
    };
    onGameEnd(results);
  };

  const handleFinishTraining = () => finishGame(score, mistakes);

  // --- Logic Helpers ---
  const handleBookSelect = (book: BookData) => {
    if (isVerified) return;
    if (selectedBookId === book.id) setSelectedBookId(null);
    else setSelectedBookId(book.id);
  };

  const handleSlotClick = (slotIndex: number) => {
    if (isVerified) return;
    if (selectedBookId) {
        const bookToPlace = availableBooks.find(b => b.id === selectedBookId);
        if (bookToPlace) {
            placeBookInSlot(bookToPlace, slotIndex);
            setSelectedBookId(null);
        }
        return;
    }
    // Return to bank
    const slot = slots[slotIndex];
    if (slot.book) {
        setAvailableBooks(prev => [...prev, slot.book!]);
        setSlots(prev => prev.map((s, i) => i === slotIndex ? { ...s, book: null, status: 'empty' } : s));
    }
  };

  const placeBookInSlot = (book: BookData, slotIndex: number) => {
    setAvailableBooks(prev => prev.filter(b => b.id !== book.id));
    const currentSlotBook = slots[slotIndex].book;
    if (currentSlotBook) setAvailableBooks(prev => [...prev, currentSlotBook]);

    setSlots(prev => prev.map((s, i) => i === slotIndex ? { ...s, book: book, status: 'placed' } : s));
  };

  const checkOrder = () => {
    let currentScore = 0;
    let currentMistakes = mistakes;
    let allCorrect = true;

    const newSlots = slots.map((slot, index) => {
        if (!slot.book) return slot;
        const correctBook = sortedCorrectBooks[index];
        const isCorrect = slot.book.id === correctBook.id;

        if (isCorrect) currentScore++;
        else {
            currentMistakes++;
            allCorrect = false;
        }
        return { ...slot, status: isCorrect ? 'correct' : 'incorrect' } as PlacedBook;
    });

    setSlots(newSlots);
    setScore(currentScore);
    setMistakes(currentMistakes);

    if (allCorrect && availableBooks.length === 0) {
        setIsVerified(true);
        setTimeout(() => finishGame(currentScore, currentMistakes), 1500);
    } else {
        setTimeout(() => {
            setSlots(prev => prev.map(s => {
                if (s.status === 'incorrect') {
                    if (s.book) setAvailableBooks(p => [...p, s.book!]);
                    return { ...s, book: null, status: 'empty' }; 
                }
                return s;
            }));
        }, 800);
    }
  };

  // --- Drag & Drop ---
  const handleDragStart = (e: React.DragEvent, book: BookData) => {
    if (isVerified) return;
    e.dataTransfer.setData("text/plain", book.id);
    e.dataTransfer.effectAllowed = "move";
  };

  const handleDragOver = (e: React.DragEvent) => {
    if (isVerified) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e: React.DragEvent, slotIndex: number) => {
    if (isVerified) return;
    e.preventDefault();
    const bookId = e.dataTransfer.getData("text/plain");
    let book = availableBooks.find(b => b.id === bookId);

    if (!book) { // Move from another slot
        const sourceSlot = slots.find(s => s.book?.id === bookId);
        if (sourceSlot && sourceSlot.book) {
            book = sourceSlot.book;
            setSlots(prev => prev.map(s => s.slotIndex === sourceSlot.slotIndex ? { ...s, book: null, status: 'empty' } : s));
        }
    }
    if (book) placeBookInSlot(book, slotIndex);
  };

  const handleInfoClick = (e: React.MouseEvent, book: BookData) => {
      e.stopPropagation();
      setInfoModalBook(book);
  };

  // Helper for label
  const getCriteriaLabel = () => {
      if (difficulty.criteria === 'ALPHABETICAL') return 'A-Z';
      if (difficulty.criteria === 'CHRONOLOGICAL') return 'Crono';
      return 'Bíblico';
  };

  return (
    <div className="flex flex-col min-h-[600px] relative pt-20 pb-4 bg-white/30 backdrop-blur-md rounded-xl shadow-xl w-full">
      {/* Header */}
      <div className="fixed top-0 left-1/2 transform -translate-x-1/2 w-full max-w-4xl px-4 py-2 bg-white/80 backdrop-blur-sm shadow-md z-20 rounded-b-xl">
        <div className="max-w-4xl mx-auto flex justify-between items-center text-sm text-gray-700">
           <div className="flex items-center gap-2">
               <span className="font-bold text-amber-600">Orden: {difficulty.label}</span>
               {isTraining && <button onClick={handleFinishTraining} className="text-xs bg-red-100 text-red-600 px-2 py-1 rounded font-bold">Terminar</button>}
           </div>
           {!isTraining && difficulty.timerDuration && difficulty.timerDuration > 0 && (
             <span className={`font-mono font-bold ${timeLeft < 15 ? 'text-red-500 anim-pulse' : 'text-gray-600'}`}>⏱ {timeLeft}s</span>
           )}
        </div>
        {!isTraining && <ProgressBar current={slots.filter(s => s.status === 'correct').length} total={books.length} />}
      </div>

      <div className="flex-grow flex flex-col p-2 sm:p-4 gap-4 overflow-hidden">

        {/* Horizontal Shelf (Slots) */}
        <div className="w-full overflow-x-auto pb-6 pt-2">
            {/* Height adjusted for smaller books */}
            <div className="flex space-x-2 px-2 min-w-max items-end h-36 sm:h-40"> 
                {slots.map((slot, index) => (
                    <div
                        key={`slot-${slot.slotIndex}`}
                        onClick={() => handleSlotClick(slot.slotIndex)}
                        onDragOver={handleDragOver}
                        onDrop={(e) => handleDrop(e, slot.slotIndex)}
                        // Width and Height of Slot Reduced
                        className={`
                            relative w-16 h-28 sm:w-20 sm:h-32 border-b-4 rounded-t-sm flex items-end justify-center transition-all duration-300
                            ${slot.status === 'empty' ? 'border-gray-300 bg-gray-50/30' : ''}
                            ${slot.status === 'placed' ? 'border-amber-700' : ''}
                            ${slot.status === 'correct' ? 'border-green-600' : ''}
                            ${slot.status === 'incorrect' ? 'border-red-500 anim-shake' : ''}
                            ${selectedBookId && !slot.book ? 'bg-amber-100/50' : ''}
                        `}
                    >   
                         {/* Slot Number Label */}
                         <div className="absolute -bottom-6 left-1/2 transform -translate-x-1/2 text-gray-500 font-mono text-[10px] font-bold">
                            #{index + 1}
                         </div>

                         {/* Empty Slot Placeholder */}
                         {!slot.book && (
                             <div className="w-full h-full border border-dashed border-gray-300 rounded-t-sm flex items-center justify-center">
                                 <span className="text-gray-300 text-xl font-bold">+</span>
                             </div>
                         )}

                         {/* Placed Book */}
                         {slot.book && (
                             <div 
                                className={`
                                    w-full h-[95%] rounded-r-sm rounded-l-xs shadow-sm flex flex-col items-center justify-center p-1 cursor-pointer relative group mx-0.5 mb-0.5
                                    ${slot.status === 'correct' ? 'bg-green-600 text-white' : ''}
                                    ${slot.status === 'incorrect' ? 'bg-red-500 text-white' : ''}
                                    ${slot.status === 'placed' ? 'bg-amber-800 text-amber-50' : ''}
                                `}
                                onDoubleClick={() => setInfoModalBook(slot.book)}
                                style={{
                                    boxShadow: 'inset 2px 0 3px rgba(0,0,0,0.2), 1px 1px 2px rgba(0,0,0,0.3)'
                                }}
                             >
                                <span className="text-[10px] sm:text-xs font-serif font-bold leading-tight text-center break-words">{slot.book.name}</span>

                                {/* Info Button (Very small) */}
                                <button 
                                    onClick={(e) => handleInfoClick(e, slot.book!)}
                                    className="absolute -top-1 -right-1 bg-black/20 hover:bg-black/40 rounded-full p-0.5 text-white/80"
                                >
                                    <InfoIcon className="w-2.5 h-2.5" />
                                </button>
                             </div>
                         )}
                    </div>
                ))}
                {/* Extra spacer at end */}
                <div className="w-4 flex-shrink-0"></div>
            </div>
            {/* Shelf Wood Plank visual */}
            <div className="h-3 w-full min-w-max bg-amber-800 rounded-sm shadow-md mt-[-1px] mx-1"></div>
        </div>

        {/* Book Bank (Bottom) */}
        <div className="flex-grow bg-white/40 rounded-t-xl border-t border-white/50 p-3 sm:p-4 overflow-y-auto shadow-inner">
            <p className="text-center text-xs text-gray-600 mb-2 italic">
                {selectedBookId 
                    ? "Toca un hueco vacío en el estante." 
                    : "Arrastra para ordenar."}
            </p>
            <div className="flex flex-wrap justify-center gap-2 pb-20">
                {availableBooks.map(book => (
                    <div
                        key={book.id}
                        draggable={!isVerified}
                        onDragStart={(e) => handleDragStart(e, book)}
                        onClick={() => handleBookSelect(book)}
                        onDoubleClick={() => setInfoModalBook(book)}
                        className={`
                            w-14 h-20 sm:w-16 sm:h-24 bg-amber-700 text-amber-50 rounded-r-sm rounded-l-xs shadow-md flex items-center justify-center p-1 cursor-grab active:cursor-grabbing hover:bg-amber-600 transition-transform relative
                            ${selectedBookId === book.id ? 'ring-2 ring-amber-300 scale-105 z-10' : ''}
                        `}
                        style={{
                            boxShadow: 'inset 2px 0 3px rgba(0,0,0,0.2), 1px 1px 2px rgba(0,0,0,0.2)'
                        }}
                    >
                        <span className="text-[10px] sm:text-xs font-serif font-bold text-center leading-tight">{book.name}</span>
                         <button 
                            onClick={(e) => handleInfoClick(e, book)}
                            className="absolute top-0.5 right-0.5 text-amber-200/50 hover:text-white"
                         >
                             <InfoIcon className="w-2.5 h-2.5" />
                         </button>
                    </div>
                ))}
                {availableBooks.length === 0 && !isVerified && (
                     <p className="text-gray-500 italic mt-8 text-sm">Estante lleno.</p>
                )}
            </div>
        </div>
      </div>

      {/* Footer Action */}
      <div className="fixed bottom-0 w-full max-w-2xl p-4 bg-white/90 backdrop-blur-md border-t border-gray-200 z-20 self-center rounded-t-xl">
         <Button onClick={checkOrder} variant="primary" className="w-full shadow-lg" disabled={slots.some(s => s.book === null) || isVerified}>
            {isVerified ? "¡Completado!" : "Verificar Orden"}
         </Button>
      </div>

      {/* Info Modal */}
      {infoModalBook && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 anim-fade-in" onClick={() => setInfoModalBook(null)}>
            <div className="bg-white rounded-xl shadow-2xl p-6 max-w-sm w-full relative" onClick={e => e.stopPropagation()}>
                <h3 className="text-2xl font-serif text-amber-700 font-bold mb-1">{infoModalBook.name}</h3>
                <p className="text-sm text-gray-500 mb-4">{infoModalBook.testament === 'Old' ? 'Antiguo Testamento' : 'Nuevo Testamento'} • Autor: {infoModalBook.author}</p>
                <div className="bg-amber-50 p-3 rounded-lg border border-amber-100 mb-4">
                    <p className="text-gray-700 text-sm leading-relaxed">{infoModalBook.summary}</p>
                </div>
                <div className="grid grid-cols-2 gap-2 text-xs text-gray-600">
                    <div className="bg-gray-100 p-2 rounded">Orden Bíblico: #{infoModalBook.canonicalOrder}</div>
                    <div className="bg-gray-100 p-2 rounded">Orden Crono (aprox): #{infoModalBook.chronologicalOrder}</div>
                </div>
                <Button onClick={() => setInfoModalBook(null)} variant="secondary" className="w-full mt-4 py-2">Cerrar</Button>
            </div>
        </div>
      )}
    </div>
  );
};

