    if (category && category !== TriviaCategory.ALL && category !== TriviaCategory.BIBLE_SUMMARIES && category !== TriviaCategory.CHAPTER_COUNTS) {
      sourceForMemory = TRIVIA_SOURCE_DATA.filter(item => item.category === category);
